def neighbors(schema, anchor, limit):
    """Return model proximity with explicit pair and relative-order feedback applied."""
    with database() as conn:
        rows = conn.execute(f"SELECT CASE WHEN r.left_id=%s THEN r.right_id ELSE r.left_id END AS other, r.score, r.judgment->>'relation', e.label FROM {schema}.relation r JOIN {schema}.entry e ON e.id=CASE WHEN r.left_id=%s THEN r.right_id ELSE r.left_id END WHERE r.left_id=%s OR r.right_id=%s", (anchor, anchor, anchor, anchor)).fetchall()
        ranked = {other: {"id": other, "score": score, "relation": relation, "label": label} for other, score, relation, label in rows}
        for left, right, score, label in conn.execute(f"SELECT left_id,right_id,score,label FROM {schema}.pair_feedback WHERE left_id=%s OR right_id=%s", (anchor, anchor)):
            other = right if left == anchor else left
            if other not in ranked:
                item = conn.execute(f"SELECT label FROM {schema}.entry WHERE id=%s", (other,)).fetchone()
                ranked[other] = {"id": other, "label": item[0] if item else None}
            ranked[other].update({"score": score, "relation": label, "feedback": True})
        ordered = sorted(ranked.values(), key=lambda item: (-item["score"], item["id"]))
        constraints = conn.execute(f"SELECT closer_id,farther_id FROM {schema}.order_feedback WHERE anchor_id=%s", (anchor,)).fetchall()
        output = apply_order_feedback(ordered, constraints)
        print(json.dumps(output[:limit], ensure_ascii=False, indent=2))


"""Screen fetched web text against the saved bookmark before profiling."""
import json
import os
import re
from urllib.parse import urlparse, urlunparse

from .cli import canonical, database, do_chat, model_json


GENERIC_LABELS = {"home", "pricing", "blog", "documentation", "features", "about us", "overview", "welcome", "login", "sign in", "post"}
PRIVATE_PATHS = {
    "chatgpt.com": ("/c/",),
    "mail.google.com": ("/mail/",),
    "perplexity.ai": ("/search/",),
    "lovable.dev": ("/projects/",),
    "linkedin.com": ("/feed/", "/search/",),
}


def normalized(value):
    """Compare titles without punctuation and formatting differences."""
    return re.sub(r"[^a-z0-9]", "", str(value).casefold())


def identity_candidate(label, url, fetched_text):
    """Select only likely identity conflicts for a model check."""
    parsed = urlparse(url or "")
    host = (parsed.hostname or "").removeprefix("www.")
    path = parsed.path.lower()
    if any((host == domain or host.endswith("." + domain)) and any(path.startswith(prefix) for prefix in prefixes) for domain, prefixes in PRIVATE_PATHS.items()):
        return True
    if not fetched_text.strip() or len(fetched_text.strip()) < 40:
        return True
    fetched_title = fetched_text.split("\n", 1)[0]
    if re.search(r"\b(?:login|log in|sign in)\b", fetched_title, flags=re.I) and not re.search(r"\b(?:login|log in|sign in)\b", label or "", flags=re.I):
        return True
    saved_head = re.split(r"\s+[|—–·]\s+|\s+-\s+", label or "", 1)[0].strip()
    if saved_head == label and len(saved_head.split()) != 1:
        return False
    if not 4 <= len(saved_head) <= 30 or len(saved_head.split()) > 3 or saved_head.casefold() in GENERIC_LABELS:
        return False
    return normalized(saved_head) not in normalized(fetched_title)


def classify_identity(label, url, description, fetched_text, model):
    """Resolve a candidate against saved identity and current page content."""
    system = "Compare a saved web bookmark with text fetched later from its URL. Return only JSON with status (accepted or quarantined) and reason (one short sentence). Accept only if the fetched text describes the same saved page or substantially the same product, article, or subject. Quarantine when a redirect, product pivot, unrelated replacement, generic login page, empty page, or unauthenticated fallback prevents the saved page from being understood. A company successor or rebrand with a substantially changed product should be quarantined because the saved bookmark's original identity must remain authoritative. Mere copy edits, pricing changes, or a renamed version of the same product are accepted. If evidence is insufficient, quarantine. Do not treat the same domain alone as proof of identity."
    parsed = urlparse(url or "")
    safe_url = urlunparse((parsed.scheme, parsed.netloc, parsed.path, "", "", ""))
    user = canonical({"saved_title": label, "saved_url": safe_url, "saved_description": str(description or "")[:1200], "fetched_title": fetched_text.split("\n", 1)[0][:300], "fetched_text": fetched_text[:3500]})
    messages = [{"role": "system", "content": system}, {"role": "user", "content": user}]
    usage = {"prompt_tokens": 0, "cache_read_input_tokens": 0, "completion_tokens": 0}
    seconds = 0.0
    for tokens in (450, 800):
        raw, used, elapsed = do_chat(model, messages, tokens)
        for key in usage:
            usage[key] += used.get(key, 0)
        seconds += elapsed
        try:
            answer = model_json(raw)
        except (json.JSONDecodeError, ValueError):
            continue
        if isinstance(answer, dict) and answer.get("status") in ("accepted", "quarantined") and isinstance(answer.get("reason"), str) and answer["reason"].strip():
            return answer["status"], answer["reason"].strip()[:300], usage, seconds
    return "quarantined", "identity could not be verified after two invalid classifier responses", usage, seconds


def pending_count(schema):
    """Count unscreened or superseded web extraction decisions."""
    with database() as conn:
        return conn.execute(f"SELECT count(*) FROM {schema}.extraction x JOIN {schema}.source_record n ON n.resource='node' AND n.id=substring(x.kind from 5) LEFT JOIN {schema}.web_identity w ON w.entry_id=x.entry_id AND w.kind=x.kind WHERE left(x.kind,4)='web:' AND NOT x.partial AND (w.entry_id IS NULL OR w.saved_hash<>n.sha256 OR w.extraction_updated_at<>x.updated_at)").fetchone()[0]


def screen_web_identity(schema, model, entry_ids=None, limit=None):
    """Persist resumable page identity decisions and discard contaminated projections."""
