                cur.executemany(f"INSERT INTO {schema}.web_identity(entry_id,kind,saved_hash,extraction_updated_at,status,reason,model) VALUES (%s,%s,%s,%s,'accepted','saved title and fetched page do not show an identity conflict','identity-rule-v1') ON CONFLICT(entry_id,kind) DO UPDATE SET saved_hash=excluded.saved_hash,extraction_updated_at=excluded.extraction_updated_at,status=excluded.status,reason=excluded.reason,model=excluded.model,decided_at=now()", [(row[0], row[1], row[4], row[3]) for row in automatic])
    print(f"web identity: {len(automatic)} matched automatically, {len(candidates)} model checks", flush=True)
