            conn.execute(f"INSERT INTO {schema}.inference_call(stage,target_key,model,input_tokens,cached_input_tokens,output_tokens,seconds) VALUES (%s,%s,%s,%s,%s,%s,%s)", ("web_identity", kind, model, usage["prompt_tokens"], usage["cache_read_input_tokens"], usage["completion_tokens"], seconds))
            if status == "quarantined":
                conn.execute(f"DELETE FROM {schema}.relation WHERE left_id=%s OR right_id=%s", (entry_id, entry_id))
                conn.execute(f"DELETE FROM {schema}.embedding WHERE entry_id=%s", (entry_id,))
