def parse_legacy(value):
    if isinstance(value, str) and value[:1] in ("{", "["):
        try:
            return json.loads(value)
        except json.JSONDecodeError:
            pass
    return value


def node_ref(value):
    """Treat legacy empty sentinels as absent node references."""
    return value if isinstance(value, str) and value.startswith("node:") else None


def resolve_roots(nodes):
    """Resolve parent chains, missing parents, and reciprocal clip/resource cycles."""
    priority = {kind: index for index, kind in enumerate(("WEB_PAGE", "TWITTER_PROFILE", "YOUTUBE_VIDEO", "NODULAR_MARKDOWN", "REDDIT_PROFILE", "AUDIO", "IMAGE", "PDF"))}
    resolved = {}
    for start in nodes:
        path, seen, current = [], {}, start
        while current not in resolved:
            if current in seen:
                cycle = path[seen[current]:]
                root = min(cycle, key=lambda record_id: (priority.get(nodes[record_id].get("contentType"), 99), record_id))
                break
            seen[current] = len(path)
            path.append(current)
            parent = node_ref(nodes[current].get("creationContext")) or node_ref(nodes[current].get("parent"))
            if not parent or parent not in nodes:
                root = current
                break
            current = parent
        else:
            root = resolved[current]
        for record_id in path:
            resolved[record_id] = root
    return resolved


def text_parts(value):
    """Extract text from legacy serialized bodies without treating IDs as prose."""
    value = parse_legacy(value)
    if isinstance(value, str):
        return [value] if value else []
    if isinstance(value, list):
        return [part for item in value for part in text_parts(item)]
    if isinstance(value, dict):
        return [part for key in ("text", "description", "transcription", "quote", "title", "value", "content", "markdown") if key in value for part in text_parts(value[key])]
    return []


