def merge_segment_profiles(partials, overview=None):
    """Retain all segment evidence while using a concise model overview when valid."""
    merged = {"summary": "", "concepts": [], "tags": [], "properties": {}, "claims": [], "domains": [], "uncertainty": []}
    summaries = []
    seen_claims = set()
    seen_facts = set()
    warnings = []
    for part in partials:
        if not isinstance(part, dict):
            raise ValueError("invalid segment profile")
        if isinstance(part.get("summary"), str) and part["summary"].strip():
            summaries.append(part["summary"].strip())
        for key in ("concepts", "tags", "domains", "uncertainty"):
            values = part.get(key)
            if not isinstance(values, list):
                raise ValueError("invalid segment profile")
            for value in values:
                already_present = any(concept_key(existing) == concept_key(value) for existing in merged[key]) if key in ("concepts", "tags", "domains") else value in merged[key]
                if isinstance(value, str) and not already_present:
                    merged[key].append(value)
        if not isinstance(part.get("properties"), dict) or not isinstance(part.get("claims"), list):
            raise ValueError("invalid segment profile")
        for key, value in part["properties"].items():
            if key in merged["properties"] and merged["properties"][key] != value:
                previous = merged["properties"][key]
                values = previous if isinstance(previous, list) else [previous]
                if value not in values:
                    merged["properties"][key] = values + [value]
                if not part.get("property_facts"):
                    warning = f"Different segment values for property {key}"
                    if warning not in merged["uncertainty"]:
                        merged["uncertainty"].append(warning)
                        warnings.append(warning)
            else:
                merged["properties"][key] = value
        for claim in part["claims"]:
            if isinstance(claim, dict):
                identifiers = claim.get("evidence_id")
                identifiers = identifiers if isinstance(identifiers, list) else [identifiers]
                for evidence_id in identifiers:
                    if isinstance(evidence_id, str):
                        evidence_id = evidence_id.strip("[]")
                    identifier = (claim.get("text"), evidence_id, claim.get("passage_id"))
                    if isinstance(identifier[0], str) and isinstance(evidence_id, str) and identifier not in seen_claims:
                        seen_claims.add(identifier)
                        merged["claims"].append({**claim, "text": identifier[0], "evidence_id": evidence_id})
        for fact in part.get("property_facts", []):
            identifier = (fact.get("key"), canonical(fact.get("value")), fact.get("passage_id")) if isinstance(fact, dict) else None
            if identifier and identifier not in seen_facts:
                seen_facts.add(identifier)
                merged.setdefault("property_facts", []).append(fact)
    merged["summary"] = "\n".join(summaries)
    if isinstance(overview, dict):
        if isinstance(overview.get("summary"), str) and overview["summary"].strip():
            merged["summary"] = overview["summary"]
        if isinstance(overview.get("uncertainty"), list) and all(isinstance(item, str) for item in overview["uncertainty"]):
            merged["uncertainty"] = list(dict.fromkeys(warnings + [item for item in overview["uncertainty"] if not re.search(r"\b(?:passages?|segments?)\b.*\b(?:truncated|missing|absent)\b", item, flags=re.I)]))
    if merged.get("property_facts"):
        merged["properties"] = properties_from_facts(merged["property_facts"])
    return merged


