function summaryList(items) {
  const wrapper = element('div', 'tags');
  for (const item of items || []) wrapper.append(element('span', 'tag', item));
  return wrapper;
}

function layoutGroup(nodes, edges, rules, width, height) {
  const columns = Math.max(1, Math.ceil(Math.sqrt(nodes.length)));
  const rows = Math.max(1, Math.ceil(nodes.length / columns));
  const points = nodes.map((node, index) => ({id: node.id, x: width * (index % columns + 1) / (columns + 1), y: height * (Math.floor(index / columns) + 1) / (rows + 1)}));
  const lookup = new Map(points.map((point, index) => [point.id, index]));
  const scores = new Map(edges.map(edge => [[edge.left, edge.right].sort().join('|'), edge.score]));
  for (let step = 0; step < 140; step++) {
    const move = points.map(() => ({x: 0, y: 0}));
    for (let a = 0; a < points.length; a++) {
      for (let b = a + 1; b < points.length; b++) {
        const dx = points[b].x - points[a].x || .01;
        const dy = points[b].y - points[a].y || .01;
        const distance = Math.hypot(dx, dy);
        const score = scores.get([points[a].id, points[b].id].sort().join('|'));
        const target = score === undefined ? 390 : 195 + (1 - score) * 380;
        if (score === undefined && distance > target) continue;
        const force = (distance - target) * (score === undefined ? .012 : .065);
        const mx = force * dx / distance;
        const my = force * dy / distance;
        move[a].x += mx;
        move[a].y += my;
        move[b].x -= mx;
        move[b].y -= my;
      }
    }
    for (const rule of rules) {
      const ai = lookup.get(rule.anchor);
      const ci = lookup.get(rule.closer);
      const fi = lookup.get(rule.farther);
      if (ai === undefined || ci === undefined || fi === undefined) continue;
      const anchor = points[ai];
      const closer = points[ci];
      const farther = points[fi];
      const near = Math.hypot(closer.x - anchor.x, closer.y - anchor.y);
      const far = Math.hypot(farther.x - anchor.x, farther.y - anchor.y);
      if (near + 55 < far) continue;
      const push = Math.min(12, (near + 55 - far) * .12);
      move[ci].x += (anchor.x - closer.x) / Math.max(near, 1) * push;
      move[ci].y += (anchor.y - closer.y) / Math.max(near, 1) * push;
      move[fi].x += (farther.x - anchor.x) / Math.max(far, 1) * push;
      move[fi].y += (farther.y - anchor.y) / Math.max(far, 1) * push;
    }
    points.forEach((point, index) => {
      point.x = Math.max(115, Math.min(width - 115, point.x + move[index].x));
      point.y = Math.max(135, Math.min(height - 115, point.y + move[index].y));
    });
  }
  return points;
}

function renderGroup(slot, data) {
  const canvas = slot.querySelector('.group-canvas');
  canvas.replaceChildren();
  for (const [id, owner] of visiblePositions) if (owner.slot === slot) visiblePositions.delete(id);
  const width = Math.max(720, Math.ceil(Math.sqrt(data.nodes.length)) * 270 + 200);
  const height = Math.max(440, viewport.clientHeight - 104);
  canvas.style.width = `${width}px`;
  canvas.style.height = `${height}px`;
  slot.style.width = `${width + 32}px`;
  const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
  svg.setAttribute('viewBox', `0 0 ${width} ${height}`);
  svg.setAttribute('aria-hidden', 'true');
  svg.classList.add('group-edges');
  const nodesLayer = element('div', 'group-nodes');
  const positions = layoutGroup(data.nodes, data.edges, data.order_feedback, width, height);
  const pointById = new Map(positions.map(point => [point.id, point]));
  for (const edge of data.edges) {
    const left = pointById.get(edge.left);
    const right = pointById.get(edge.right);
    if (!left || !right) continue;
    const line = document.createElementNS('http://www.w3.org/2000/svg', 'line');
    line.setAttribute('x1', left.x);
    line.setAttribute('y1', left.y);
    line.setAttribute('x2', right.x);
    line.setAttribute('y2', right.y);
    line.setAttribute('stroke-width', String(1.2 + edge.score * 2));
    line.setAttribute('opacity', String(.22 + edge.score * .53));
    svg.append(line);
  }
  for (const node of data.nodes) {
    const point = pointById.get(node.id);
    if (!point) continue;
    const card = button('', () => openEntry(node.id), `node${node.quality === 'thin' ? ' thin' : ''}${node.context ? ' context' : ''}`);
    card.style.left = `${point.x}px`;
    card.style.top = `${point.y}px`;
    card.append(element('span', 'type', (node.type || 'Memory').replaceAll('_', ' ')));
    card.append(element('span', 'label', node.label || node.id));
    card.append(element('span', 'meta', (node.concepts || []).slice(0, 2).join(' · ') || node.quality));
    nodesLayer.append(card);
    visiblePositions.set(node.id, {slot, point});
  }
  canvas.append(svg, nodesLayer);
  const pager = slot.querySelector('.group-pager');
  pager.replaceChildren();
  if (data.pages > 1) {
    const prev = button('Previous', () => loadGroup(slot, data.page - 1));
    prev.disabled = data.page === 0;
    const next = button('Next', () => loadGroup(slot, data.page + 1));
    next.disabled = data.page + 1 >= data.pages;
    pager.append(prev, element('span', '', `Entries ${data.page * PAGE_SIZE + 1}-${Math.min(data.size, (data.page + 1) * PAGE_SIZE)} of ${data.size}`), next);
  }
}

async function loadGroup(slot, page = 0) {
  const ticket = String(Number(slot.dataset.ticket || 0) + 1);
  slot.dataset.ticket = ticket;
  slot.dataset.page = String(page);
  slot.querySelector('.group-canvas').replaceChildren(element('p', 'group-loading', 'Loading connected memories...'));
  slot.querySelector('.group-pager').replaceChildren();
  try {
    const data = await request(`/api/map/group?id=${encodeURIComponent(slot.dataset.id)}&page=${page}`);
    if (slot.dataset.ticket !== ticket || !slot.isConnected) return;
    if (!data) {
      slot.querySelector('.group-canvas').replaceChildren(element('p', 'group-loading', 'This group changed during inference. Refresh the map to see the current groups.'));
      return;
    }
    renderGroup(slot, data);
  } catch {
    if (slot.dataset.ticket === ticket) slot.querySelector('.group-canvas').replaceChildren(element('p', 'group-loading', 'Could not load this group.'));
  }
}

const groupObserver = new IntersectionObserver(entries => {
  for (const entry of entries) {
    const slot = entry.target;
    if (entry.isIntersecting) {
      if (slot.dataset.loaded !== 'true') {
        slot.dataset.loaded = 'true';
        loadGroup(slot, Number(slot.dataset.page || 0));
      }
    } else if (slot.dataset.loaded === 'true') {
      slot.dataset.loaded = 'false';
      slot.dataset.ticket = String(Number(slot.dataset.ticket || 0) + 1);
      slot.querySelector('.group-canvas').replaceChildren();
      slot.querySelector('.group-pager').replaceChildren();
      for (const [id, owner] of visiblePositions) if (owner.slot === slot) visiblePositions.delete(id);
    }
  }
}, {root: viewport, rootMargin: '700px 700px 0px 700px'});

async function loadMoreGroups() {
  if (loadingGroups || nextGroupOffset === null) return;
  loadingGroups = true;
  document.getElementById('more-groups').hidden = false;
  try {
    const data = await request(`/api/map/groups?offset=${nextGroupOffset}&limit=8`);
    const start = nextGroupOffset;
    nextGroupOffset = data.next_offset;
    document.getElementById('coverage').textContent = `${data.connected_entries.toLocaleString()} connected / ${data.total_entries.toLocaleString()} saved`;
    document.getElementById('map-status').textContent = `${data.group_count} groups · ${data.profiled_entries.toLocaleString()} profiled`;
    for (const [index, group] of data.groups.entries()) {
      const slot = element('section', 'group-slot');
      slot.dataset.id = group.id;
      slot.dataset.page = '0';
      slot.style.width = `${Math.max(800, Math.ceil(Math.sqrt(Math.min(group.size, PAGE_SIZE))) * 270 + 232)}px`;
      const heading = element('div', 'group-heading');
      heading.append(element('span', 'eyebrow', `Proximity group ${start + index + 1}`), element('strong', '', `${group.size} connected memories`));
      slot.append(heading, element('div', 'group-canvas'), element('div', 'group-pager'));
      track.append(slot);
      groupObserver.observe(slot);
    }
    if (!data.groups.length && start === 0) track.append(element('p', 'empty-map', 'No connected groups have been judged yet. Search or browse the library to inspect saved memories.'));
  } catch {
    document.getElementById('map-status').textContent = 'Graph unavailable';
  } finally {
    loadingGroups = false;
    document.getElementById('more-groups').hidden = true;
  }
}

function checkMapEnd() {
  if (view === 'map' && nextGroupOffset !== null && viewport.scrollLeft + viewport.clientWidth >= viewport.scrollWidth - 1000) loadMoreGroups();
}

async function openEntry(id) {
