.more-groups{align-self:center;min-width:250px;color:#a5c1c0}
.node{position:absolute;transform:translate(-50%,-50%);width:190px;min-height:92px;text-align:left;background:#152a31;border:1px solid #447176;border-radius:13px;padding:12px 14px;color:#e5f2f3;box-shadow:0 9px 22px #0007}
.node:hover,.node:focus{outline:2px solid #a9e6d7;z-index:2}
.node .type{color:#9bd1c4;font-size:10px;letter-spacing:.13em;text-transform:uppercase}
.node .label{display:block;font-size:14px;font-weight:600;line-height:1.32;margin:7px 0;word-break:break-word;max-height:56px;overflow:hidden}
.node .meta{display:block;color:#86a0a5;font-size:11px;line-height:1.3}
.node.thin{border-style:dashed;opacity:.78}
.node.context{border-color:#617c7e;background:#102128;opacity:.78}
#library{overflow:auto;background:#09171d;padding:30px max(32px,calc((100vw - 1200px)/2));scrollbar-color:#4d7779 #102029}
.library-head{display:flex;justify-content:space-between;align-items:end;gap:24px;margin-bottom:26px}
.library-head h1{font-size:30px;margin:7px 0 5px;letter-spacing:-.04em}
.library-head p:not(.eyebrow){color:#91aeb2;margin:0;font-size:14px}
.library-search{width:280px;flex:none}
.resources{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:28px}
.resources button{border:1px solid #36535a;background:#12262e;color:#b9d0d1;border-radius:9px;padding:9px 13px;font-size:13px}
.resources button.active{border-color:#8fcdc1;background:#254d4c;color:#edfcf8}
.records-head{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #36515a;padding:0 2px 14px;font-size:14px;font-weight:600}
.records-head #records-count{font-size:12px;color:#89a6a9;font-weight:400}
.records{min-height:180px}
.record-row{display:flex;justify-content:space-between;align-items:center;gap:18px;width:100%;text-align:left;color:#dcebec;background:transparent;border:0;border-bottom:1px solid #20343c;padding:16px 6px}
.record-row:hover,.record-row:focus{background:#142b32}
.record-body{min-width:0;display:flex;flex-direction:column;gap:6px}
.record-body strong{font-size:14px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.record-body small{color:#87a4a9;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:740px;font-size:12px}
.record-badges{display:flex;gap:6px;flex:none}
.record-badges span{border:1px solid #38565b;border-radius:6px;padding:4px 7px;font-size:10px;color:#a7c2c5;text-transform:uppercase;letter-spacing:.05em}
.record-badges .good{color:#a9e6d7;border-color:#4f877e}
.records-loading{padding:32px;color:#8eabb2}
.record-pages{display:flex;align-items:center;justify-content:center;gap:16px;margin:25px 0 40px;color:#9ab4b6;font-size:13px}
aside{position:absolute;z-index:5;top:76px;right:0;bottom:40px;width:min(520px,96vw);background:#0f2028;border-left:1px solid #416067;box-shadow:-18px 0 50px #0008;overflow-y:auto;padding:23px}
aside button{background:#1f3941;border:1px solid #53767a;border-radius:8px;color:#ecf5f5;padding:8px 12px}
aside .primary-button{margin-top:12px;background:#28544e;border-color:#81bdb0}
aside h1{font-size:22px;line-height:1.25;overflow-wrap:anywhere;margin:8px 0}
aside h2{font-size:13px;text-transform:uppercase;letter-spacing:.12em;color:#9ec8c2;margin:0 0 12px}
aside p,aside li{line-height:1.5;color:#c2d5d8;font-size:13px}
aside pre{white-space:pre-wrap;word-break:break-word;font:12px/1.55 ui-monospace,monospace;background:#102d32;padding:14px;border-radius:8px;color:#d0e6e7;max-height:380px;overflow:auto}
.detail-section{border-top:1px solid #29454d;margin-top:22px;padding-top:20px}
.detail-meta{overflow-wrap:anywhere;color:#93acb1}
.source-link{display:block;color:#a8e2d6;font-size:12px;overflow-wrap:anywhere}
.tags{display:flex;flex-wrap:wrap;gap:5px}
.tag{display:inline-block;padding:4px 7px;background:#244049;border-radius:5px;color:#c7e0de;font-size:11px}
.neighbor-list{display:flex;flex-direction:column;gap:7px}
.neighbor-list button{text-align:left}
.notice{padding:12px;background:#26343c;border-radius:8px}
.status-grid{display:grid;grid-template-columns:1fr 1fr;gap:9px}
.status-cell{display:flex;flex-direction:column;gap:5px;background:#17323a;padding:10px;border-radius:7px;min-width:0}
.status-cell span{color:#91b0b3;font-size:11px}
.status-cell strong{font-size:12px;overflow-wrap:anywhere}
footer{height:40px;border-top:1px solid #203039;background:#0b171e;display:flex;justify-content:space-between;align-items:center;padding:0 24px;color:#78969c;font-size:12px;gap:14px}
