function focusEntry(id) {
  const owner = visiblePositions.get(id);
  if (owner && view === 'map') viewport.scrollTo({left: Math.max(0, owner.slot.offsetLeft + owner.point.x - viewport.clientWidth / 2), behavior: 'smooth'});
  openEntry(id);
}

async function openRecord(resource, id, displayLabel) {
  detail.hidden = false;
  detailContent.replaceChildren(element('p', '', 'Loading source record...'));
  try {
    const record = await request(`/api/library/record?resource=${encodeURIComponent(resource)}&id=${encodeURIComponent(id)}`);
    if (!record) throw new Error('Missing record');
    detailContent.replaceChildren(element('p', 'eyebrow', `Authoritative ${resource} record`), element('h1', '', record.source.label || displayLabel || record.id));
    detailContent.append(element('p', 'detail-meta', `${record.id} · ingested ${new Date(record.ingested_at).toLocaleString()}`));
    if (record.entry_id) detailContent.append(button('Open projected memory', () => openEntry(record.entry_id), 'primary-button'));
    detailContent.append(section('Source fields', formatted(record.source)));
    if (record.entry) {
      const status = element('div', 'status-grid');
      for (const [key, value] of Object.entries({Evidence: record.entry.evidence_quality, Profile: record.projection?.profile_model || 'Pending', Embedding: record.projection?.embedding_model || 'Pending', 'Judged pairs': record.projection?.judged_pairs ?? 0})) {
        const cell = element('div', 'status-cell');
        cell.append(element('span', '', key), element('strong', '', value));
        status.append(cell);
      }
      detailContent.append(section('Projection status', status));
      if (record.entry.profile) {
        detailContent.append(section('AI summary', element('p', '', record.entry.profile.summary || 'No summary')));
        detailContent.append(section('Concepts and tags', summaryList([...(record.entry.profile.concepts || []), ...(record.entry.profile.tags || [])])));
        detailContent.append(section('Extracted properties', formatted(record.entry.profile.properties || {})));
        if (record.entry.profile.claims?.length) detailContent.append(section('Cited claims', formatted(record.entry.profile.claims)));
      }
      detailContent.append(section(`Combined evidence${record.entry.evidence_truncated ? ' · excerpt' : ''}`, formatted(record.entry.evidence_text || 'No source text')));
      for (const extraction of record.entry.extractions) detailContent.append(section(`${extraction.kind} · ${extraction.model || 'unknown model'}${extraction.partial ? ' · partial' : ''}${extraction.truncated ? ' · excerpt' : ''}`, formatted(extraction.text)));
      if (record.entry.extraction_failures.length) detailContent.append(section('Extraction failures', formatted(record.entry.extraction_failures)));
    } else detailContent.append(element('p', 'notice', 'No entry projection is associated with this source record.'));
  } catch {
    detailContent.replaceChildren(element('p', 'notice', 'Could not load this source record.'));
  }
}

function setView(next) {
  view = next;
  const map = next === 'map';
  viewport.hidden = !map;
  library.hidden = map;
  document.getElementById('map-tab').classList.toggle('active', map);
  document.getElementById('library-tab').classList.toggle('active', !map);
  document.getElementById('map-tab').setAttribute('aria-current', map ? 'page' : 'false');
  document.getElementById('library-tab').setAttribute('aria-current', map ? 'false' : 'page');
  document.getElementById('view-hint').textContent = map ? 'Scroll horizontally to explore connected memories. Select one to inspect its evidence.' : 'Source records are authoritative; projections are derived and can be reprocessed.';
  if (!map && !resourceNav.childElementCount) loadResources();
  if (map) checkMapEnd();
}

async function loadResources() {
  try {
    const resources = await request('/api/library/resources');
    resourceNav.replaceChildren();
    for (const item of resources) {
      const control = button(`${item.resource} ${item.count.toLocaleString()}`, () => {
        selectedResource = item.resource;
        libraryPage = 0;
        librarySearch.value = '';
        updateResourceSelection();
        loadRecords();
      });
      control.dataset.resource = item.resource;
      resourceNav.append(control);
    }
    updateResourceSelection();
    loadRecords();
  } catch {
    recordsElement.replaceChildren(element('p', 'notice', 'Library unavailable.'));
  }
}

function updateResourceSelection() {
  for (const control of resourceNav.querySelectorAll('button')) {
    const active = control.dataset.resource === selectedResource;
    control.classList.toggle('active', active);
    control.setAttribute('aria-current', active ? 'page' : 'false');
  }
}

async function loadRecords() {
  const ticket = ++libraryTicket;
  recordsElement.replaceChildren(element('p', 'records-loading', 'Loading records...'));
  recordPages.replaceChildren();
  const query = librarySearch.value.trim();
  try {
    const data = await request(`/api/library/records?resource=${encodeURIComponent(selectedResource)}&page=${libraryPage}&q=${encodeURIComponent(query)}`);
    if (ticket !== libraryTicket) return;
    document.getElementById('records-title').textContent = `${selectedResource} records`;
    document.getElementById('records-count').textContent = `${data.total.toLocaleString()} records`;
    recordsElement.replaceChildren();
    for (const record of data.records) {
      const row = button('', () => openRecord(data.resource, record.id, record.label), 'record-row');
      const body = element('span', 'record-body');
      body.append(element('strong', '', record.label || record.id), element('small', '', record.excerpt || record.url || record.id));
      const badges = element('span', 'record-badges');
      badges.append(element('span', '', (record.content_type || selectedResource).replaceAll('_', ' ')));
      if (record.profiled) badges.append(element('span', 'good', 'Profiled'));
      else if (record.evidence_quality) badges.append(element('span', '', 'Projected'));
      row.append(body, badges);
      recordsElement.append(row);
    }
    if (!data.records.length) recordsElement.append(element('p', 'records-loading', 'No matching records.'));
    const previous = button('Previous', () => { libraryPage--; loadRecords(); });
    previous.disabled = data.page === 0;
    const next = button('Next', () => { libraryPage++; loadRecords(); });
    next.disabled = data.page + 1 >= data.pages;
    recordPages.append(previous, element('span', '', `Page ${data.pages ? data.page + 1 : 0} of ${data.pages}`), next);
  } catch {
    if (ticket === libraryTicket) recordsElement.replaceChildren(element('p', 'notice', 'Could not load records.'));
  }
}

