  results.hidden = false;
  searchTimer = setTimeout(async () => {
    try {
      const entries = await request(`/api/search?q=${encodeURIComponent(text)}`);
      if (text !== searchInput.value.trim()) return;
      results.replaceChildren();
      for (const entry of entries) {
        const item = button(entry.label || entry.id, () => { results.hidden = true; focusEntry(entry.id); });
        item.append(element('small', '', `${entry.content_type.replaceAll('_', ' ')} · ${entry.profiled ? 'profiled' : 'searchable'}`));
        results.append(item);
      }
      if (!entries.length) results.append(element('p', '', 'No matching memories'));
    } catch { results.hidden = true; }
  }, 250);
});

