cd /Users/serro/Documents/dev/n/agent/experiments/mgraph

worker_count=${MGRAPH_PROFILE_WORKERS:-4}
if [[ ! "$worker_count" =~ '^[1-9][0-9]*$' ]]; then
  print "MGRAPH_PROFILE_WORKERS must be a positive integer"
  exit 2
fi

print "m graph stage: web identity screening"
uv run python -m mgraph migrate || exit 1
uv run python -m mgraph screen-web-identity || exit 1
uv run python -m mgraph repair-profile-names || exit 1

print "m graph stage: Kimi profiles, $worker_count disjoint shards"
typeset -a worker_pids
for (( shard = 0; shard < worker_count; shard++ )); do
  uv run python -m mgraph profile --model kimi-k3 --shard "$shard" --shards "$worker_count" &
  worker_pids+=("$!")
done

failed=0
for worker_pid in "${worker_pids[@]}"; do
  wait "$worker_pid" || failed=1
done
if (( failed != 0 )); then
  print "m graph profiling paused; one or more shards failed"
  exit 1
fi

set -e
print "m graph stage: saved title repair"
uv run python -m mgraph repair-profile-names
print "m graph stage: profile audit"
uv run python -m mgraph audit-profiles --model kimi-k3
print "m graph stage: Cloudflare embeddings"
uv run python -m mgraph embed
print "m graph stage: Kimi relations, first 20000 distinct pairs"
uv run python -m mgraph relate --target-total 20000
print "m graph stage: final status"
uv run python -m mgraph status
"}}}

