 59	function layoutGroup(nodes, edges, rules, width, height) {
 60	  const columns = Math.max(1, Math.ceil(Math.sqrt(nodes.length)));
 61	  const rows = Math.max(1, Math.ceil(nodes.length / columns));
 62	  const points = nodes.map((node, index) => ({id: node.id, x: width * (index % columns + 1) / (columns + 1), y: height * (Math.floor(index / columns) + 1) / (rows + 1)}));
 63	  const lookup = new Map(points.map((point, index) => [point.id, index]));
 64	  const scores = new Map(edges.map(edge => [[edge.left, edge.right].sort().join('|'), edge.score]));
 65	  for (let step = 0; step < 140; step++) {
 66	    const move = points.map(() => ({x: 0, y: 0}));
 67	    for (let a = 0; a < points.length; a++) {
 68	      for (let b = a + 1; b < points.length; b++) {
 69	        const dx = points[b].x - points[a].x || .01;
 70	        const dy = points[b].y - points[a].y || .01;
 71	        const distance = Math.hypot(dx, dy);
 72	        const score = scores.get([points[a].id, points[b].id].sort().join('|'));
 73	        const target = score === undefined ? 390 : 195 + (1 - score) * 380;
 74	        if (score === undefined && distance > target) continue;
 75	        const force = (distance - target) * (score === undefined ? .012 : .065);
 76	        const mx = force * dx / distance;
 77	        const my = force * dy / distance;
 78	        move[a].x += mx;
 79	        move[a].y += my;
 80	        move[b].x -= mx;
 81	        move[b].y -= my;
 82	      }
 83	    }
