 85	      const ai = lookup.get(rule.anchor);
 86	      const ci = lookup.get(rule.closer);
 87	      const fi = lookup.get(rule.farther);
 88	      if (ai === undefined || ci === undefined || fi === undefined) continue;
 89	      const anchor = points[ai];
 90	      const closer = points[ci];
 91	      const farther = points[fi];
 92	      const near = Math.hypot(closer.x - anchor.x, closer.y - anchor.y);
 93	      const far = Math.hypot(farther.x - anchor.x, farther.y - anchor.y);
 94	      if (near + 55 < far) continue;
 95	      const push = Math.min(12, (near + 55 - far) * .12);
 96	      move[ci].x += (anchor.x - closer.x) / Math.max(near, 1) * push;
 97	      move[ci].y += (anchor.y - closer.y) / Math.max(near, 1) * push;
 98	      move[fi].x += (farther.x - anchor.x) / Math.max(far, 1) * push;
 99	      move[fi].y += (farther.y - anchor.y) / Math.max(far, 1) * push;
100	    }
101	    points.forEach((point, index) => {
102	      point.x = Math.max(115, Math.min(width - 115, point.x + move[index].x));
103	      point.y = Math.max(135, Math.min(height - 115, point.y + move[index].y));
104	    });
195	    }
