"""Build strong-link clusters and an evidence-aware neighboring order."""
import heapq
import math
from collections import defaultdict


def connected_components(edges, threshold, visible_ids=None):
    """Group nodes linked at a threshold, retaining selected isolated nodes."""
    adjacency = defaultdict(list)
    for edge in edges.values():
        if edge["score"] < threshold:
            continue
        adjacency[edge["left"]].append((edge["right"], edge["score"]))
        adjacency[edge["right"]].append((edge["left"], edge["score"]))
    candidates = set(adjacency) if visible_ids is None else set(visible_ids)
    seen = set()
    components = []
    for start in sorted(candidates):
        if start in seen:
            continue
        pending = [start]
        members = set()
        while pending:
            current = pending.pop()
            if current in seen:
                continue
            seen.add(current)
            members.add(current)
            pending.extend(other for other, _ in adjacency[current] if other not in seen)
        root = max(members, key=lambda item: (sum(score for _, score in adjacency[item]), -len(item), item))
        traversal = [root]
        parents = {root: None}
        frontier = [(-score, root, other) for other, score in adjacency[root]]
        heapq.heapify(frontier)
        while frontier:
            negative_score, parent, child = heapq.heappop(frontier)
            if child in parents:
                continue
            parents[child] = parent
            traversal.append(child)
            for other, score in adjacency[child]:
                if other not in parents:
                    heapq.heappush(frontier, (-score, child, other))
        components.append({"id": min(members), "size": len(members), "anchor": root, "members": traversal, "parents": parents})
    return components


def _normalized_vector(raw):
    values = [float(value) for value in raw.strip("[]").split(",")] if isinstance(raw, str) else [float(value) for value in raw]
    magnitude = math.sqrt(sum(value * value for value in values))
    return [value / magnitude for value in values] if magnitude else None


def _centroid(component, vectors):
    members = [_normalized_vector(vectors[entry_id]) for entry_id in component["members"] if entry_id in vectors]
    members = [member for member in members if member]
    if not members:
        return None
    totals = [sum(values) for values in zip(*members)]
    magnitude = math.sqrt(sum(value * value for value in totals))
    return [value / magnitude for value in totals] if magnitude else None


def neighboring_clusters(edges, vectors, visible_threshold=0.65, cluster_threshold=0.8):
    """Split visible judged links into tight clusters and order nearby clusters."""
    visible = {entry_id for edge in edges.values() if edge["score"] >= visible_threshold for entry_id in (edge["left"], edge["right"])}
    clusters = connected_components(edges, cluster_threshold, visible)
    if not clusters:
        return []
    owner = {entry_id: cluster["id"] for cluster in clusters for entry_id in cluster["members"]}
    centroids = {cluster["id"]: _centroid(cluster, vectors) for cluster in clusters}
    cross_scores = defaultdict(list)
    for edge in edges.values():
        left = owner.get(edge["left"])
        right = owner.get(edge["right"])
        if left is not None and right is not None and left != right:
            cross_scores[tuple(sorted((left, right)))].append(edge["score"])
    affinities = {}
    for index, left in enumerate(clusters):
        for right in clusters[index + 1:]:
            key = tuple(sorted((left["id"], right["id"])))
            judged = cross_scores.get(key)
            if judged:
                score = max(judged)
                affinities[key] = (2 + score if score >= visible_threshold else score, {"basis": "judged", "score": score, "pair_count": len(judged)})
                continue
            first = centroids[left["id"]]
            second = centroids[right["id"]]
            if first is not None and second is not None:
                score = sum(a * b for a, b in zip(first, second))
                affinities[key] = (score, {"basis": "embedding", "score": score})
            else:
                affinities[key] = (-2, {"basis": "unknown"})
    remaining = {cluster["id"]: cluster for cluster in clusters}
    first = sorted(remaining.values(), key=lambda cluster: (-cluster["size"], cluster["id"]))[0]
    ordered = [{**first, "neighbor": None}]
    del remaining[first["id"]]
    while remaining:
        previous = ordered[-1]
        nearest = sorted(remaining.values(), key=lambda cluster: (-affinities[tuple(sorted((previous["id"], cluster["id"])))][0], -cluster["size"], cluster["id"]))[0]
        link = affinities[tuple(sorted((previous["id"], nearest["id"])))][1]
        ordered.append({**nearest, "neighbor": link})
        del remaining[nearest["id"]]
    return ordered

