.search-wrap{position:relative;width:min(400px,28vw)}
input{background:#13242d;border:1px solid #34505a;border-radius:10px;color:#eff9fb;padding:11px 14px;width:100%;outline:none}
input:focus,button:focus-visible{outline:2px solid #a9e6d7;outline-offset:2px}
.coverage{margin-left:auto;color:#93aab1;font-size:13px;white-space:nowrap}
.results{position:absolute;top:50px;left:0;right:0;max-height:430px;overflow:auto;background:#14242b;border:1px solid #3b5961;box-shadow:0 18px 40px #0008;border-radius:10px;padding:6px;z-index:8}
