#world{height:100%;min-width:100%;width:max-content;display:flex;align-items:stretch;background-image:linear-gradient(#9accc50c 1px,transparent 1px),linear-gradient(90deg,#9accc50c 1px,transparent 1px);background-size:80px 80px}
