.record-body{min-width:0;display:flex;flex-direction:column;gap:6px}
.record-body strong{font-size:14px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.record-body small{color:#87a4a9;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:740px;font-size:12px}
