aside{position:absolute;z-index:5;top:76px;right:0;bottom:40px;width:min(520px,96vw);background:#0f2028;border-left:1px solid #416067;box-shadow:-18px 0 50px #0008;overflow-y:auto;padding:23px}
aside button{background:#1f3941;border:1px solid #53767a;border-radius:8px;color:#ecf5f5;padding:8px 12px}
aside .primary-button{margin-top:12px;background:#28544e;border-color:#81bdb0}
aside h1{font-size:22px;line-height:1.25;overflow-wrap:anywhere;margin:8px 0}
