aside p,aside li{line-height:1.5;color:#c2d5d8;font-size:13px}
aside pre{white-space:pre-wrap;word-break:break-word;font:12px/1.55 ui-monospace,monospace;background:#102d32;padding:14px;border-radius:8px;color:#d0e6e7;max-height:380px;overflow:auto}
