"""Read-only queries shared by the local MCP server and map prototype."""
import heapq
import json
import threading
import time

from .cli import apply_order_feedback, config, database, text_parts
from .profile_quality import normalize_property_key


def accepted_extraction(schema, alias="x"):
    """Use web text only after its saved-page identity was screened."""
    return f"(left({alias}.kind,4)<>'web:' OR EXISTS (SELECT 1 FROM {schema}.web_identity w JOIN {schema}.source_record n ON n.resource='node' AND n.id=substring({alias}.kind from 5) WHERE w.entry_id={alias}.entry_id AND w.kind={alias}.kind AND w.status='accepted' AND w.saved_hash=n.sha256 AND w.extraction_updated_at={alias}.updated_at))"


GRAPH_THRESHOLD = 0.65
SOURCE_RESOURCES = ("node", "file", "link", "collection", "property", "linkTag")
_graph_cache = {"at": 0.0, "value": None}
_graph_lock = threading.Lock()


def _graph_index():
    """Cache compact graph topology so map pages never fetch all node profiles."""
    with _graph_lock:
        if _graph_cache["value"] is not None and time.monotonic() - _graph_cache["at"] < 30:
            return _graph_cache["value"]
        schema = config()
        with database() as conn:
            profiled = {row[0] for row in conn.execute(f"SELECT entry_id FROM {schema}.profile")}
            relation_rows = conn.execute(f"SELECT left_id,right_id,score,judgment->>'relation' FROM {schema}.relation").fetchall()
            feedback_rows = conn.execute(f"SELECT left_id,right_id,score,label FROM {schema}.pair_feedback").fetchall()
            total = conn.execute(f"SELECT count(*) FROM {schema}.entry").fetchone()[0]
        edges = {}
        for left, right, score, relation in relation_rows:
            if left in profiled and right in profiled:
                key = tuple(sorted((left, right)))
                edges[key] = {"left": key[0], "right": key[1], "score": score, "relation": relation, "feedback": False}
        for left, right, score, relation in feedback_rows:
            if left in profiled and right in profiled:
                key = tuple(sorted((left, right)))
                edges[key] = {"left": key[0], "right": key[1], "score": score, "relation": relation, "feedback": True}
        adjacency = {}
        for edge in edges.values():
            if edge["score"] < GRAPH_THRESHOLD:
                continue
            adjacency.setdefault(edge["left"], []).append((edge["right"], edge["score"]))
            adjacency.setdefault(edge["right"], []).append((edge["left"], edge["score"]))
        seen = set()
        groups = []
        for start in sorted(adjacency):
            if start in seen:
                continue
            pending = [start]
            members = set()
            while pending:
                current = pending.pop()
                if current in seen:
                    continue
                seen.add(current)
                members.add(current)
                pending.extend(other for other, _ in adjacency[current] if other not in seen)
            root = max(members, key=lambda item: (sum(score for _, score in adjacency[item]), -len(item), item))
            traversal = [root]
            parents = {root: None}
            frontier = [(-score, root, other) for other, score in adjacency[root]]
            heapq.heapify(frontier)
            while frontier:
                negative_score, parent, child = heapq.heappop(frontier)
                if child in parents:
                    continue
                parents[child] = parent
                traversal.append(child)
                for other, score in adjacency[child]:
                    if other not in parents:
                        heapq.heappush(frontier, (-score, child, other))
            groups.append({"id": min(members), "size": len(members), "anchor": root, "members": traversal, "parents": parents})
        groups.sort(key=lambda group: (-group["size"], group["id"]))
        value = {"groups": groups, "edges": edges, "total_entries": total, "profiled_entries": len(profiled)}
        _graph_cache.update(at=time.monotonic(), value=value)
        return value


def map_groups(offset=0, limit=8):
    """Return one page of connected proximity groups and map coverage."""
    graph = _graph_index()
    offset = max(0, int(offset))
    limit = max(1, min(int(limit), 20))
    groups = graph["groups"][offset:offset + limit]
    return {"total_entries": graph["total_entries"], "profiled_entries": graph["profiled_entries"], "connected_entries": sum(group["size"] for group in graph["groups"]), "group_count": len(graph["groups"]), "offset": offset, "next_offset": offset + limit if offset + limit < len(graph["groups"]) else None, "groups": [{"id": group["id"], "size": group["size"], "anchor": group["anchor"]} for group in groups]}


def map_group(group_id, page=0, page_size=24):
    """Return a bounded connected slice, with bridge nodes for page boundaries."""
    graph = _graph_index()
    group = next((item for item in graph["groups"] if item["id"] == group_id), None)
    if group is None:
        return None
    page = max(0, int(page))
    page_size = max(2, min(int(page_size), 32))
    selected = group["members"][page * page_size:(page + 1) * page_size]
    context = {group["parents"][item] for item in selected if group["parents"][item] and group["parents"][item] not in selected}
    ids = selected + sorted(context)
    if not ids:
        return {"id": group_id, "size": group["size"], "page": page, "page_size": page_size, "pages": (group["size"] + page_size - 1) // page_size, "nodes": [], "edges": [], "order_feedback": []}
    schema = config()
    with database() as conn:
        rows = conn.execute(f"SELECT e.id,e.label,e.content_type,e.evidence_quality,p.profile FROM {schema}.entry e JOIN {schema}.profile p ON p.entry_id=e.id WHERE e.id=ANY(%s)", (ids,)).fetchall()
        rules = conn.execute(f"SELECT anchor_id,closer_id,farther_id FROM {schema}.order_feedback WHERE anchor_id=ANY(%s) AND closer_id=ANY(%s) AND farther_id=ANY(%s)", (ids, ids, ids)).fetchall()
    id_set = set(ids)
    context_set = set(context)
    nodes = [{"id": row[0], "label": row[1], "type": row[2], "quality": row[3], "concepts": row[4].get("concepts", [])[:5], "tags": row[4].get("tags", [])[:5], "context": row[0] in context_set} for row in rows]
    edges = [edge for edge in graph["edges"].values() if edge["score"] >= GRAPH_THRESHOLD and edge["left"] in id_set and edge["right"] in id_set]
    return {"id": group_id, "size": group["size"], "page": page, "page_size": page_size, "pages": (group["size"] + page_size - 1) // page_size, "nodes": nodes, "edges": edges, "order_feedback": [{"anchor": row[0], "closer": row[1], "farther": row[2]} for row in rules]}


def library_resources():
    """Count authoritative source records by legacy Memotron resource."""
    schema = config()
    with database() as conn:
        counts = dict(conn.execute(f"SELECT resource,count(*) FROM {schema}.source_record GROUP BY resource").fetchall())
    return [{"resource": resource, "count": counts.get(resource, 0)} for resource in SOURCE_RESOURCES]


def library_records(resource, page=0, page_size=30, search="", profiled_only=False):
    """Page authoritative records with compact projection status for list rendering."""
    if resource not in SOURCE_RESOURCES:
        raise ValueError("Unknown resource")
    page = max(0, int(page))
    page_size = max(1, min(int(page_size), 50))
    search = search.strip()[:200]
    schema = config()
    condition = "s.resource=%s"
    args = [resource]
    if profiled_only:
        if resource != "node":
            raise ValueError("Profiled entries are only available for node records")
        condition += f" AND EXISTS (SELECT 1 FROM {schema}.profile selected_profile WHERE selected_profile.entry_id=s.id)"
    if search:
        condition += " AND (s.id ILIKE %s OR s.payload->>'label' ILIKE %s OR s.payload->>'url' ILIKE %s OR s.payload->>'text' ILIKE %s OR s.payload->>'body' ILIKE %s)"
        args.extend([f"%{search}%"] * 5)
    with database() as conn:
        total = conn.execute(f"SELECT count(*) FROM {schema}.source_record s WHERE {condition}", args).fetchone()[0]
        rows = conn.execute(f"SELECT s.id,s.payload,s.ingested_at,e.evidence_quality,p.entry_id IS NOT NULL,v.entry_id IS NOT NULL FROM {schema}.source_record s LEFT JOIN {schema}.entry e ON s.resource='node' AND e.id=s.id LEFT JOIN {schema}.profile p ON p.entry_id=e.id LEFT JOIN {schema}.embedding v ON v.entry_id=e.id WHERE {condition} ORDER BY s.payload->>'modifiedAt' DESC NULLS LAST,s.id LIMIT %s OFFSET %s", (*args, page_size, page * page_size)).fetchall()
    records = []
    for record_id, payload, ingested_at, quality, profiled, embedded in rows:
        prose = " ".join(text_parts(payload.get("text")) + text_parts(payload.get("body")) + text_parts(payload.get("metadata"))).strip()
        prose = " ".join(prose.split())
        label = payload.get("label")
        if not isinstance(label, str) or not label.strip():
            label = prose[:110] or payload.get("url") or record_id
        records.append({"id": record_id, "label": label, "content_type": payload.get("contentType") or payload.get("type") or payload.get("linkType"), "url": payload.get("url"), "excerpt": prose[:220], "modified_at": payload.get("modifiedAt"), "ingested_at": ingested_at.isoformat(), "evidence_quality": quality, "profiled": profiled, "embedded": embedded})
    return {"resource": resource, "page": page, "page_size": page_size, "total": total, "pages": (total + page_size - 1) // page_size, "records": records}


def library_record(resource, record_id):
    """Pair one authoritative record with its available derived graph projection."""
    if resource not in SOURCE_RESOURCES:
        raise ValueError("Unknown resource")
    schema = config()
    with database() as conn:
        row = conn.execute(f"SELECT payload,sha256,ingested_at FROM {schema}.source_record WHERE resource=%s AND id=%s", (resource, record_id)).fetchone()
        if row is None:
            return None
        entry_id = record_id if resource == "node" and conn.execute(f"SELECT 1 FROM {schema}.entry WHERE id=%s", (record_id,)).fetchone() else None
        if entry_id is None and resource in ("node", "file"):
            reference = [{"id": record_id}] if resource == "node" else [{"file": record_id}]
            match = conn.execute(f"SELECT id FROM {schema}.entry WHERE evidence_refs @> %s::jsonb LIMIT 1", (json.dumps(reference),)).fetchone()
            entry_id = match[0] if match else None
        projected = conn.execute(f"SELECT p.model,p.prompt_version,p.updated_at,v.model,(SELECT count(*) FROM {schema}.relation r WHERE r.left_id=%s OR r.right_id=%s) FROM {schema}.profile p LEFT JOIN {schema}.embedding v ON v.entry_id=p.entry_id WHERE p.entry_id=%s", (entry_id, entry_id, entry_id)).fetchone() if entry_id else None
    return {"resource": resource, "id": record_id, "source": row[0], "source_sha256": row[1], "ingested_at": row[2].isoformat(), "entry_id": entry_id, "entry": get_entry(entry_id) if entry_id else None, "projection": {"profile_model": projected[0], "prompt_version": projected[1], "profiled_at": projected[2].isoformat(), "embedding_model": projected[3], "judged_pairs": projected[4]} if projected else None}


def search_entries(query, limit=20):
    """Search every projected entry, including entries without an AI profile."""
    schema = config()
    limit = max(1, min(int(limit), 100))
    accepted = accepted_extraction(schema)
    with database() as conn:
        rows = conn.execute(f"WITH needle AS (SELECT plainto_tsquery('english',%s) AS tsq) SELECT e.id,e.label,e.content_type,CASE WHEN e.evidence_quality='rich' OR EXISTS (SELECT 1 FROM {schema}.extraction x WHERE x.entry_id=e.id AND NOT x.partial AND {accepted} AND length(x.text_content)>=400) THEN 'rich' ELSE e.evidence_quality END,p.profile IS NOT NULL AS profiled,ts_rank(to_tsvector('english',coalesce(e.label,'') || ' ' || e.evidence_text),n.tsq) AS rank FROM {schema}.entry e LEFT JOIN {schema}.profile p ON p.entry_id=e.id CROSS JOIN needle n WHERE e.id ILIKE %s OR e.label ILIKE %s OR to_tsvector('english',coalesce(e.label,'') || ' ' || e.evidence_text) @@ n.tsq OR EXISTS (SELECT 1 FROM {schema}.extraction x WHERE x.entry_id=e.id AND NOT x.partial AND {accepted} AND to_tsvector('english',x.text_content) @@ n.tsq) ORDER BY rank DESC,e.label NULLS LAST,e.id LIMIT %s", (query, f"%{query}%", f"%{query}%", limit)).fetchall()
    return [{"id": row[0], "label": row[1], "content_type": row[2], "evidence_quality": row[3], "profiled": row[4], "rank": float(row[5])} for row in rows]


def get_entry(entry_id, max_chars=12000, include_quarantined=True):
    """Return source-cited evidence, extracted media, and the current profile."""
    schema = config()
    max_chars = max(100, min(int(max_chars), 40000))
    accepted = accepted_extraction(schema)
    with database() as conn:
        row = conn.execute(f"SELECT e.id,e.label,e.content_type,e.url,CASE WHEN e.evidence_quality='rich' OR EXISTS (SELECT 1 FROM {schema}.extraction x WHERE x.entry_id=e.id AND NOT x.partial AND {accepted} AND length(x.text_content)>=400) THEN 'rich' ELSE e.evidence_quality END,e.evidence_text,e.evidence_refs,p.profile,p.model FROM {schema}.entry e LEFT JOIN {schema}.profile p ON p.entry_id=e.id WHERE e.id=%s", (entry_id,)).fetchone()
        if not row:
            return None
        extra = conn.execute(f"SELECT x.kind,CASE WHEN NOT x.partial AND (%s OR {accepted}) THEN left(x.text_content,%s) ELSE NULL END,x.model,x.partial,length(x.text_content),CASE WHEN x.partial THEN 'partial' WHEN {accepted} THEN 'accepted' WHEN w.status='quarantined' AND w.saved_hash=n.sha256 AND w.extraction_updated_at=x.updated_at THEN 'quarantined' ELSE 'pending' END,w.reason,w.model FROM {schema}.extraction x LEFT JOIN {schema}.web_identity w ON w.entry_id=x.entry_id AND w.kind=x.kind LEFT JOIN {schema}.source_record n ON n.resource='node' AND n.id=substring(x.kind from 5) WHERE x.entry_id=%s ORDER BY x.kind", (include_quarantined, max_chars, entry_id)).fetchall()
        failures = conn.execute(f"SELECT source_id,kind,error_type,status FROM {schema}.extraction_failure WHERE entry_id=%s ORDER BY kind,source_id", (entry_id,)).fetchall()
    return {"id": row[0], "label": row[1], "content_type": row[2], "url": row[3], "evidence_quality": row[4], "evidence_text": row[5][:max_chars], "evidence_truncated": len(row[5]) > max_chars, "evidence_refs": row[6], "profile": row[7], "profile_model": row[8], "extractions": [{"kind": kind, "text": text, "model": model, "partial": partial, "truncated": length > max_chars if text else False, "identity_status": identity_status, "identity_reason": identity_reason, "identity_model": identity_model} for kind, text, model, partial, length, identity_status, identity_reason, identity_model in extra], "extraction_failures": [{"source_id": source_id, "kind": kind, "error_type": error_type, "status": status} for source_id, kind, error_type, status in failures]}


def neighbors(entry_id, limit=20):
    """Get judged neighbors with user pair and ordering feedback applied."""
    schema = config()
    limit = max(1, min(int(limit), 100))
    with database() as conn:
        rows = conn.execute(f"SELECT CASE WHEN r.left_id=%s THEN r.right_id ELSE r.left_id END,r.score,r.judgment->>'relation',e.label FROM {schema}.relation r JOIN {schema}.entry e ON e.id=CASE WHEN r.left_id=%s THEN r.right_id ELSE r.left_id END WHERE r.left_id=%s OR r.right_id=%s", (entry_id, entry_id, entry_id, entry_id)).fetchall()
        ranked = {other: {"id": other, "score": score, "relation": relation, "label": label} for other, score, relation, label in rows}
        for left, right, score, label in conn.execute(f"SELECT left_id,right_id,score,label FROM {schema}.pair_feedback WHERE left_id=%s OR right_id=%s", (entry_id, entry_id)):
            other = right if left == entry_id else left
            if other not in ranked:
                item = conn.execute(f"SELECT label FROM {schema}.entry WHERE id=%s", (other,)).fetchone()
                ranked[other] = {"id": other, "label": item[0] if item else None}
            ranked[other].update({"score": score, "relation": label, "feedback": True})
        constraints = conn.execute(f"SELECT closer_id,farther_id FROM {schema}.order_feedback WHERE anchor_id=%s", (entry_id,)).fetchall()
    return apply_order_feedback(sorted(ranked.values(), key=lambda item: (-item["score"], item["id"])), constraints)[:limit]


def compare_entries(left_id, right_id):
    """Return the persisted comparison and its evidence, without new inference."""
    schema = config()
    left_id, right_id = sorted((left_id, right_id))
    with database() as conn:
        relation = conn.execute(f"SELECT judgment,score,model,updated_at FROM {schema}.relation WHERE left_id=%s AND right_id=%s", (left_id, right_id)).fetchone()
        feedback = conn.execute(f"SELECT score,label,note FROM {schema}.pair_feedback WHERE left_id=%s AND right_id=%s", (left_id, right_id)).fetchone()
    return {"left_id": left_id, "right_id": right_id, "judgment": relation[0] if relation else None, "score": relation[1] if relation else None, "model": relation[2] if relation else None, "updated_at": relation[3].isoformat() if relation else None, "feedback": {"score": feedback[0], "label": feedback[1], "note": feedback[2]} if feedback else None}


def comparison_matrix(left_id, right_id):
    """Assemble persisted property rows and cited claims for an agent's table."""
    schema = config()
    with database() as conn:
        rows = conn.execute(f"SELECT e.id,e.label,p.profile FROM {schema}.entry e LEFT JOIN {schema}.profile p ON p.entry_id=e.id WHERE e.id IN (%s,%s)", (left_id, right_id)).fetchall()
        failures = conn.execute(f"SELECT entry_id,kind,status FROM {schema}.extraction_failure WHERE entry_id IN (%s,%s)", (left_id, right_id)).fetchall()
    entries = {row[0]: {"id": row[0], "label": row[1], "profile": row[2]} for row in rows}
    if left_id not in entries or right_id not in entries:
        raise ValueError("comparison entry missing")
    left = entries[left_id]
    right = entries[right_id]
    left_profile = left["profile"] or {}
    right_profile = right["profile"] or {}
    left_properties = {normalize_property_key(key): value for key, value in (left_profile.get("properties") or {}).items()}
    right_properties = {normalize_property_key(key): value for key, value in (right_profile.get("properties") or {}).items()}
    left_facts = {}
    right_facts = {}
    for fact in left_profile.get("property_facts", []):
        left_facts.setdefault(fact["key"], []).append(fact)
    for fact in right_profile.get("property_facts", []):
        right_facts.setdefault(fact["key"], []).append(fact)
    keys = sorted(set(left_properties) | set(right_properties))
    return {"left": {"id": left_id, "label": left["label"], "summary": left_profile.get("summary"), "claims": left_profile.get("claims", []), "uncertainty": left_profile.get("uncertainty", []), "missing_extractions": [{"kind": kind, "status": status} for entry, kind, status in failures if entry == left_id]}, "right": {"id": right_id, "label": right["label"], "summary": right_profile.get("summary"), "claims": right_profile.get("claims", []), "uncertainty": right_profile.get("uncertainty", []), "missing_extractions": [{"kind": kind, "status": status} for entry, kind, status in failures if entry == right_id]}, "property_rows": [{"property": key, "left": left_properties.get(key), "right": right_properties.get(key), "left_evidence": left_facts.get(key, []), "right_evidence": right_facts.get(key, [])} for key in keys], "relation": compare_entries(left_id, right_id)}


def map_data(limit=10000):
    """Provide profiled nodes and judged edges for the horizontal map."""
    schema = config()
    limit = max(1, min(int(limit), 10000))
    accepted = accepted_extraction(schema)
    with database() as conn:
        nodes = conn.execute(f"SELECT e.id,e.label,e.content_type,CASE WHEN e.evidence_quality='rich' OR EXISTS (SELECT 1 FROM {schema}.extraction x WHERE x.entry_id=e.id AND NOT x.partial AND {accepted} AND length(x.text_content)>=400) THEN 'rich' ELSE e.evidence_quality END,p.profile FROM {schema}.profile p JOIN {schema}.entry e ON e.id=p.entry_id ORDER BY e.id LIMIT %s", (limit,)).fetchall()
        ids = [node[0] for node in nodes]
        edges = conn.execute(f"SELECT left_id,right_id,score,judgment->>'relation' FROM {schema}.relation WHERE left_id=ANY(%s) AND right_id=ANY(%s)", (ids, ids)).fetchall() if ids else []
        feedback = conn.execute(f"SELECT left_id,right_id,score,label FROM {schema}.pair_feedback WHERE left_id=ANY(%s) AND right_id=ANY(%s)", (ids, ids)).fetchall() if ids else []
        order = conn.execute(f"SELECT anchor_id,closer_id,farther_id FROM {schema}.order_feedback WHERE anchor_id=ANY(%s) AND closer_id=ANY(%s) AND farther_id=ANY(%s)", (ids, ids, ids)).fetchall() if ids else []
        counts = conn.execute(f"SELECT (SELECT count(*) FROM {schema}.entry),(SELECT count(*) FROM {schema}.profile)").fetchone()

