                    usage = {"prompt_tokens": usage.get("prompt_tokens", 0) + repair_usage.get("prompt_tokens", 0), "cache_read_input_tokens": usage.get("cache_read_input_tokens", 0) + repair_usage.get("cache_read_input_tokens", 0), "completion_tokens": usage.get("completion_tokens", 0) + repair_usage.get("completion_tokens", 0)}
                    latency += repair_latency
                if not valid_relation(result, left_allowed, right_allowed):
                    raise ValueError("relation has invalid evidence IDs")
                score = float(result["score"])
                conn.execute(f"INSERT INTO {schema}.relation(left_id,right_id,model,source_hash,judgment,score) VALUES (%s,%s,%s,%s,%s,%s) ON CONFLICT(left_id,right_id) DO UPDATE SET model=excluded.model,source_hash=excluded.source_hash,judgment=excluded.judgment,score=excluded.score,updated_at=now()", (left_id, right_id, model, pair_hash, Jsonb(result), score))
                conn.execute(f"INSERT INTO {schema}.inference_call(stage,target_key,model,input_tokens,cached_input_tokens,output_tokens,seconds) VALUES (%s,%s,%s,%s,%s,%s,%s)", ("relation", left_id + "|" + right_id, model, usage.get("prompt_tokens", 0), usage.get("cache_read_input_tokens", 0), usage.get("completion_tokens", 0), latency))
                conn.commit()
                count += 1
                if not old or old[1] != model:
                    total += 1
                print(f"relation {count}: {left_id} {right_id} score={score:.2f} {latency:.1f}s {usage}", flush=True)
            except (httpx.HTTPError, ValueError, KeyError) as error:
                conn.rollback()
                print(f"relation failed {left_id} {right_id}: {type(error).__name__}: {str(error)[:150]}", flush=True)
            if limit and count >= limit:
                break


