def valid_relation(result, left_allowed, right_allowed):
    """Require bounded proximity and cited evidence from both entries."""
    if not isinstance(result, dict) or result.get("relation") not in ("same_product", "same_niche", "related_domain", "conceptual_echo", "contradiction", "unrelated"):
        return False
    try:
        score = float(result["score"])
        evidence_ids = set(result["evidence_ids"])
    except (KeyError, TypeError, ValueError):
        return False
    return 0 <= score <= 1 and evidence_ids.issubset(left_allowed | right_allowed) and bool(evidence_ids & left_allowed) and bool(evidence_ids & right_allowed)


def candidate_pairs(schema, per_entry, max_pairs):
    """Union vector neighbors, lexical matches, and explicit source links."""
    priorities = {}
    def add(left, right, priority):
        pair = tuple(sorted((left, right)))
        priorities[pair] = max(priorities.get(pair, 0), priority)
    with database() as conn:
        vectors = conn.execute(f"SELECT entry_id,vector::text FROM {schema}.embedding ORDER BY entry_id").fetchall()
        for entry_id, vector in vectors:
            neighbors = conn.execute(f"SELECT entry_id,1-(vector <=> %s::vector) FROM {schema}.embedding WHERE entry_id<>%s ORDER BY vector <=> %s::vector LIMIT %s", (vector, entry_id, vector, per_entry)).fetchall()
            for other, similarity in neighbors:
                add(entry_id, other, float(similarity))
            lexical = conn.execute(f"SELECT id FROM {schema}.entry WHERE id<>%s AND to_tsvector('english', evidence_text) @@ plainto_tsquery('english', (SELECT left(coalesce(label,''),80) FROM {schema}.entry WHERE id=%s)) LIMIT %s", (entry_id, entry_id, per_entry)).fetchall()
            for (other,) in lexical:
                add(entry_id, other, 0.68)
        concept_index = defaultdict(list)
        for entry_id, profile_data in conn.execute(f"SELECT entry_id,profile FROM {schema}.profile"):
            for concept in profile_data.get("concepts", []):
                normalized = concept_key(concept)
                if len(normalized) >= 5:
                    concept_index[normalized].append(entry_id)
        for members in concept_index.values():
            if 2 <= len(members) <= 30:
                for index, left in enumerate(members):
                    for right in members[index + 1:]:
                        add(left, right, 0.72)
        source_nodes = {record_id: payload for record_id, payload in conn.execute(f"SELECT id,payload FROM {schema}.source_record WHERE resource='node'")}
        root_map = resolve_roots(source_nodes)
        for left, right in conn.execute(f"SELECT payload->>'out',payload->>'in' FROM {schema}.source_record WHERE resource='link'"):
            left_root, right_root = root_map.get(left), root_map.get(right)
            if left_root and right_root and left_root != right_root:
                add(left_root, right_root, 0.65)
        profiled = {row[0] for row in conn.execute(f"SELECT entry_id FROM {schema}.profile")}
    eligible = sorted((pair for pair in priorities if pair[0] in profiled and pair[1] in profiled), key=lambda pair: (-priorities[pair], pair))
    return eligible[:max_pairs] if max_pairs else eligible


def should_judge_relation(old, pair_hash, model, total, target_total):
    """Preserve a durable distinct-pair cap while refreshing stale judgments."""
    if old and old[0] == pair_hash:
        return False
    return target_total is None or total < target_total or bool(old and old[1] == model)


