"""Keep parallel relation workers within a durable distinct-pair ceiling."""
import unittest
from unittest.mock import patch

from mgraph import cli


class _Rows:
    def fetchall(self):
        return [("a", "b"), ("c", "d"), ("e", "f")]


class _Database:
    def __enter__(self):
        return self

    def __exit__(self, *_):
        return False

    def execute(self, *_):
        return _Rows()


class RelationBudgetTests(unittest.TestCase):
    def test_saved_pairs_reduce_each_disjoint_shard_budget(self):
        with patch.object(cli, "database", return_value=_Database()):
            budgets = cli.relation_budgets("test", 4, 11)
        self.assertEqual(len(budgets), 4)
        self.assertEqual(sum(budgets), 8)
        self.assertTrue(all(budget >= 0 for budget in budgets))


if __name__ == "__main__":
    unittest.main()

