import { get, writable } from "svelte/store";
import { AppSkin } from "@21n/theme/appearance.type";
import { type IAppStore } from "@nucleum/shared-state/app-context/app-store.type";
import type { DragAndDrop } from "@21n/ui/actions/draganddrop.type";
import { DragStatus } from "@21n/ui/actions/dragstatus.enum";
import blankJson from "@nucleum/client/config/blank.json";
import colorSchemes from "@21n/theme/colorschemes.json";
import { Resource } from "@nucleum/datafn/resource.enum";
