CREATE TABLE IF NOT EXISTS {schema}.source_record (
  resource text NOT NULL,
  id text NOT NULL,
  payload jsonb NOT NULL,
  sha256 text NOT NULL,
  ingested_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (resource, id)
);
CREATE TABLE IF NOT EXISTS {schema}.snapshot_page (
  resource text NOT NULL,
  page_number integer NOT NULL,
  r2_key text NOT NULL,
  sha256 text NOT NULL,
  row_count integer NOT NULL,
  next_key jsonb,
  complete boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (resource, page_number)
);
ALTER TABLE {schema}.snapshot_page ADD COLUMN IF NOT EXISTS next_key jsonb;
ALTER TABLE {schema}.snapshot_page ADD COLUMN IF NOT EXISTS complete boolean NOT NULL DEFAULT false;
CREATE TABLE IF NOT EXISTS {schema}.entry (
  id text PRIMARY KEY,
  content_type text NOT NULL,
  label text,
  url text,
  source_hash text NOT NULL,
  evidence_text text NOT NULL,
  evidence_refs jsonb NOT NULL DEFAULT '[]',
  evidence_quality text NOT NULL,
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS {schema}.extraction (
  entry_id text NOT NULL REFERENCES {schema}.entry(id) ON DELETE CASCADE,
  kind text NOT NULL,
  source_hash text NOT NULL,
  text_content text NOT NULL,
  model text,
  r2_key text,
  partial boolean NOT NULL DEFAULT false,
  updated_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (entry_id, kind)
