def relation_prompt(left, right):
    return [{"role": "system", "content": "Compare two saved memory entries for graph proximity. Return only JSON with score (number 0..1), relation (same_product|same_niche|related_domain|conceptual_echo|contradiction|unrelated), shared_concepts (array), distinguishing_facts (array), explanation (string), evidence_ids (array). Be conservative: two coding tools are broadly related, while two agentic development environments are a tighter niche. Cite both entry IDs. Do not invent features absent from evidence."}, {"role": "user", "content": canonical({"left": left, "right": right})}]


def valid_relation(result, left_allowed, right_allowed):
    """Require bounded proximity and cited evidence from both entries."""
    if not isinstance(result, dict) or result.get("relation") not in ("same_product", "same_niche", "related_domain", "conceptual_echo", "contradiction", "unrelated"):
        return False
    try:
        score = float(result["score"])
        evidence_ids = set(result["evidence_ids"])
    except (KeyError, TypeError, ValueError):
        return False
    return 0 <= score <= 1 and evidence_ids.issubset(left_allowed | right_allowed) and bool(evidence_ids & left_allowed) and bool(evidence_ids & right_allowed)


def candidate_pairs(schema, per_entry, max_pairs):
    """Union vector neighbors, lexical matches, and explicit source links."""
    priorities = {}
    def add(left, right, priority):
        pair = tuple(sorted((left, right)))
        priorities[pair] = max(priorities.get(pair, 0), priority)
    with database() as conn:
        vectors = conn.execute(f"SELECT entry_id,vector::text FROM {schema}.embedding ORDER BY entry_id").fetchall()
        for entry_id, vector in vectors:
            neighbors = conn.execute(f"SELECT entry_id,1-(vector <=> %s::vector) FROM {schema}.embedding WHERE entry_id<>%s ORDER BY vector <=> %s::vector LIMIT %s", (vector, entry_id, vector, per_entry)).fetchall()
            for other, similarity in neighbors:
                add(entry_id, other, float(similarity))
            lexical = conn.execute(f"SELECT id FROM {schema}.entry WHERE id<>%s AND to_tsvector('english', evidence_text) @@ plainto_tsquery('english', (SELECT left(coalesce(label,''),80) FROM {schema}.entry WHERE id=%s)) LIMIT %s", (entry_id, entry_id, per_entry)).fetchall()
            for (other,) in lexical:
                add(entry_id, other, 0.68)
        concept_index = defaultdict(list)
        for entry_id, profile_data in conn.execute(f"SELECT entry_id,profile FROM {schema}.profile"):
            for concept in profile_data.get("concepts", []):
                normalized = concept_key(concept)
                if len(normalized) >= 5:
                    concept_index[normalized].append(entry_id)
        for members in concept_index.values():
            if 2 <= len(members) <= 30:
                for index, left in enumerate(members):
                    for right in members[index + 1:]:
                        add(left, right, 0.72)
        source_nodes = {record_id: payload for record_id, payload in conn.execute(f"SELECT id,payload FROM {schema}.source_record WHERE resource='node'")}
        root_map = resolve_roots(source_nodes)
        for left, right in conn.execute(f"SELECT payload->>'out',payload->>'in' FROM {schema}.source_record WHERE resource='link'"):
            left_root, right_root = root_map.get(left), root_map.get(right)
            if left_root and right_root and left_root != right_root:
                add(left_root, right_root, 0.65)
        profiled = {row[0] for row in conn.execute(f"SELECT entry_id FROM {schema}.profile")}
    eligible = sorted((pair for pair in priorities if pair[0] in profiled and pair[1] in profiled), key=lambda pair: (-priorities[pair], pair))
    return eligible[:max_pairs] if max_pairs else eligible


def should_judge_relation(old, pair_hash, model, total, target_total):
    """Preserve a durable distinct-pair cap while refreshing stale judgments."""
    if old and old[0] == pair_hash:
        return False
    return target_total is None or total < target_total or bool(old and old[1] == model)


def save_relation(schema, left_id, right_id, model, pair_hash, result, score, usage, latency):
    """Commit a judgment and its usage together across transient database failures."""
    for attempt in range(8):
        try:
            with database() as conn:
                conn.execute(f"INSERT INTO {schema}.relation(left_id,right_id,model,source_hash,judgment,score) VALUES (%s,%s,%s,%s,%s,%s) ON CONFLICT(left_id,right_id) DO UPDATE SET model=excluded.model,source_hash=excluded.source_hash,judgment=excluded.judgment,score=excluded.score,updated_at=now()", (left_id, right_id, model, pair_hash, Jsonb(result), score))
                conn.execute(f"INSERT INTO {schema}.inference_call(stage,target_key,model,input_tokens,cached_input_tokens,output_tokens,seconds) VALUES (%s,%s,%s,%s,%s,%s,%s)", ("relation", left_id + "|" + right_id, model, usage.get("prompt_tokens", 0), usage.get("cache_read_input_tokens", 0), usage.get("completion_tokens", 0), latency))
            return
        except (psycopg.OperationalError, psycopg.InterfaceError):
            try:
                with database() as conn:
                    persisted = conn.execute(f"SELECT source_hash,model FROM {schema}.relation WHERE left_id=%s AND right_id=%s", (left_id, right_id)).fetchone()
                if persisted == (pair_hash, model):
                    return
            except (psycopg.OperationalError, psycopg.InterfaceError):
                pass
            if attempt == 7:
                raise
            time.sleep(min(2 ** attempt, 30))


def relate(schema, limit, model, per_entry, explicit_pair=None, shard=0, shards=1, target_total=None):
    with database() as conn:
        total = conn.execute(f"SELECT count(*) FROM {schema}.relation WHERE model=%s", (model,)).fetchone()[0]
    count = 0
    pairs = [tuple(sorted(explicit_pair))] if explicit_pair else candidate_pairs(schema, per_entry, None)
    for left_id, right_id in pairs:
        if not explicit_pair and int(sha(left_id + "|" + right_id)[:8], 16) % shards != shard:
            continue
        with database() as conn:
            rows = conn.execute(f"SELECT e.id,e.content_type,e.label,p.profile,e.evidence_text,e.evidence_refs FROM {schema}.entry e LEFT JOIN {schema}.profile p ON p.entry_id=e.id WHERE e.id IN (%s,%s) ORDER BY e.id", (left_id, right_id)).fetchall()
            old = conn.execute(f"SELECT source_hash,model FROM {schema}.relation WHERE left_id=%s AND right_id=%s", (left_id, right_id)).fetchone()
        if len(rows) != 2 or not all(row[3] for row in rows):
            continue
        payloads = [{"evidence_id": row[0], "type": row[1], "label": row[2], "profile": row[3], "excerpt": row[4][:1200]} for row in rows]
        pair_hash = sha(canonical(payloads) + RELATION_VERSION + model)
        if not should_judge_relation(old, pair_hash, model, total, target_total):
            continue
        try:
            prompt = relation_prompt(*payloads)
            raw, usage, latency = do_chat(model, prompt, 3500)
            try:
                result = model_json(raw)
            except json.JSONDecodeError:
                retry_raw, retry_usage, retry_latency = do_chat(model, prompt, 6000)
                result = model_json(retry_raw)
                usage = {"prompt_tokens": usage.get("prompt_tokens", 0) + retry_usage.get("prompt_tokens", 0), "cache_read_input_tokens": usage.get("cache_read_input_tokens", 0) + retry_usage.get("cache_read_input_tokens", 0), "completion_tokens": usage.get("completion_tokens", 0) + retry_usage.get("completion_tokens", 0)}
                latency += retry_latency
            left_allowed = {rows[0][0]} | {ref["id"] for ref in rows[0][5]}
            right_allowed = {rows[1][0]} | {ref["id"] for ref in rows[1][5]}
            if not valid_relation(result, left_allowed, right_allowed):
                repair = [{"role": "system", "content": "Repair this pair judgment as JSON with the original keys. Give a 0..1 score and a supported relation label. Cite at least one allowed evidence ID from each side, and no other IDs. Remove unsupported facts."}, {"role": "user", "content": canonical({"left_allowed": sorted(left_allowed), "right_allowed": sorted(right_allowed), "judgment": result})}]
                corrected, repair_usage, repair_latency = do_chat(model, repair, 3000)
                result = model_json(corrected)
                usage = {"prompt_tokens": usage.get("prompt_tokens", 0) + repair_usage.get("prompt_tokens", 0), "cache_read_input_tokens": usage.get("cache_read_input_tokens", 0) + repair_usage.get("cache_read_input_tokens", 0), "completion_tokens": usage.get("completion_tokens", 0) + repair_usage.get("completion_tokens", 0)}
                latency += repair_latency
            if not valid_relation(result, left_allowed, right_allowed):
                raise ValueError("relation has invalid evidence IDs")
            score = float(result["score"])
            save_relation(schema, left_id, right_id, model, pair_hash, result, score, usage, latency)
            count += 1
            if not old or old[1] != model:
                total += 1
            print(f"relation {count}: {left_id} {right_id} score={score:.2f} {latency:.1f}s {usage}", flush=True)
        except (httpx.HTTPError, ValueError, KeyError) as error:
            print(f"relation failed {left_id} {right_id}: {type(error).__name__}: {str(error)[:150]}", flush=True)
        if limit and count >= limit:
            break


def refresh_stale_relations(schema, model, shard=0, shards=1):
    """Rejudge saved pairs whose evidence profiles changed after judgment."""
    with database() as conn:
        pairs = conn.execute(f"SELECT r.left_id,r.right_id FROM {schema}.relation r JOIN {schema}.profile a ON a.entry_id=r.left_id JOIN {schema}.profile b ON b.entry_id=r.right_id WHERE a.updated_at>r.updated_at OR b.updated_at>r.updated_at ORDER BY r.left_id,r.right_id").fetchall()
    selected = [(left, right) for left, right in pairs if int(sha(left + "|" + right)[:8], 16) % shards == shard]
    print(f"stale relation shard {shard + 1}/{shards}: {len(selected)} pairs", flush=True)
    for left, right in selected:
        relate(schema, 1, model, 8, explicit_pair=(left, right))
    with database() as conn:
        remaining = conn.execute(f"SELECT r.left_id,r.right_id FROM {schema}.relation r JOIN {schema}.profile a ON a.entry_id=r.left_id JOIN {schema}.profile b ON b.entry_id=r.right_id WHERE a.updated_at>r.updated_at OR b.updated_at>r.updated_at").fetchall()
    pending = sum(int(sha(left + "|" + right)[:8], 16) % shards == shard for left, right in remaining)
    print(f"stale relation shard {shard + 1}/{shards}: {pending} remaining", flush=True)
    if pending:
        raise RuntimeError(f"{pending} stale relations remain in shard {shard}")


def relation_budgets(schema, shards, target_total):
    """Split the distinct-pair ceiling across disjoint relation shards."""
    with database() as conn:
