_cluster_cache = {"graph_at": None, "value": None}
_cluster_lock = threading.Lock()


def _graph_index():
    """Cache compact graph topology so map pages never fetch all node profiles."""
    with _graph_lock:
        if _graph_cache["value"] is not None and time.monotonic() - _graph_cache["at"] < 30:
            return _graph_cache["value"]
        schema = config()
        with database() as conn:
            profiled = {row[0] for row in conn.execute(f"SELECT entry_id FROM {schema}.profile")}
            relation_rows = conn.execute(f"SELECT left_id,right_id,score,judgment->>'relation' FROM {schema}.relation").fetchall()
            feedback_rows = conn.execute(f"SELECT left_id,right_id,score,label FROM {schema}.pair_feedback").fetchall()
            total = conn.execute(f"SELECT count(*) FROM {schema}.entry").fetchone()[0]
        edges = {}
        for left, right, score, relation in relation_rows:
            if left in profiled and right in profiled:
                key = tuple(sorted((left, right)))
                edges[key] = {"left": key[0], "right": key[1], "score": score, "relation": relation, "feedback": False}
        for left, right, score, relation in feedback_rows:
            if left in profiled and right in profiled:
                key = tuple(sorted((left, right)))
                edges[key] = {"left": key[0], "right": key[1], "score": score, "relation": relation, "feedback": True}
        groups = connected_components(edges, GRAPH_THRESHOLD)
        groups.sort(key=lambda group: (-group["size"], group["id"]))
        value = {"groups": groups, "edges": edges, "total_entries": total, "profiled_entries": len(profiled)}
        _graph_cache.update(at=time.monotonic(), value=value)
        return value


def _cluster_index():
    """Cache strong clusters and their neighboring order for one graph generation."""
    graph = _graph_index()
    graph_at = _graph_cache["at"]
    with _cluster_lock:
        if _cluster_cache["graph_at"] == graph_at and _cluster_cache["value"] is not None:
            return graph, _cluster_cache["value"]
        visible = sorted({entry_id for edge in graph["edges"].values() if edge["score"] >= GRAPH_THRESHOLD for entry_id in (edge["left"], edge["right"])})
        vectors = {}
        if visible:
            schema = config()
            with database() as conn:
                vectors = dict(conn.execute(f"SELECT entry_id,vector::text FROM {schema}.embedding WHERE entry_id=ANY(%s)", (visible,)).fetchall())
        clusters = neighboring_clusters(graph["edges"], vectors, GRAPH_THRESHOLD)
        _cluster_cache.update(graph_at=graph_at, value=clusters)
        return graph, clusters


def map_clusters():
    """Return ordered strong-cluster summaries with judged or estimated links."""
    graph, clusters = _cluster_index()
    return {"total_entries": graph["total_entries"], "profiled_entries": graph["profiled_entries"], "connected_entries": sum(cluster["size"] for cluster in clusters), "cluster_count": len(clusters), "cluster_threshold": 0.8, "visible_threshold": GRAPH_THRESHOLD, "clusters": [{"id": cluster["id"], "size": cluster["size"], "anchor": cluster["anchor"], "neighbor": cluster["neighbor"]} for cluster in clusters]}


