:root{font-family:Inter,ui-sans-serif,system-ui,sans-serif;color:#dce8ec;background:#071016;font-synthesis:none}
*{box-sizing:border-box}
[hidden]{display:none!important}
body{margin:0;overflow:hidden}
button,input{font:inherit}
button{cursor:pointer}
button:disabled{cursor:default;opacity:.4}
header{height:76px;display:flex;align-items:center;gap:24px;padding:0 28px;border-bottom:1px solid #203039;background:#0b171e;position:relative;z-index:4}
.brand{display:flex;align-items:center;gap:11px;font-size:21px;font-weight:700;white-space:nowrap;letter-spacing:-.04em}
.brand small{font-size:11px;font-weight:500;letter-spacing:.12em;text-transform:uppercase;color:#82a0a8}
.brand-mark{display:grid;place-items:center;width:35px;height:35px;border-radius:11px;background:#a9e6d7;color:#0b2927;font-size:25px}
.view-switch{display:flex;gap:4px;padding:4px;background:#12242c;border-radius:10px;white-space:nowrap}
.view-switch button{border:0;background:transparent;color:#a8bdc1;border-radius:7px;padding:8px 12px;font-size:13px}
.view-switch button.active{background:#2b4c50;color:#edfcf8}
.search-wrap{position:relative;width:min(400px,28vw)}
input{background:#13242d;border:1px solid #34505a;border-radius:10px;color:#eff9fb;padding:11px 14px;width:100%;outline:none}
input:focus,button:focus-visible{outline:2px solid #a9e6d7;outline-offset:2px}
.coverage{margin-left:auto;color:#93aab1;font-size:13px;white-space:nowrap}
.results{position:absolute;top:50px;left:0;right:0;max-height:430px;overflow:auto;background:#14242b;border:1px solid #3b5961;box-shadow:0 18px 40px #0008;border-radius:10px;padding:6px;z-index:8}
.results button{display:block;width:100%;text-align:left;border:0;background:none;color:#eaf2f3;padding:10px;border-radius:6px}
