  heading.append(element('p', 'eyebrow', 'Saved proximity graph'), element('h1', '', activeGroup ? data.groups.find(group => group.id === activeGroup)?.label || 'Group' : 'Clusters'), element('p', '', 'Select a cluster to expand its memories and inspect every ranked neighbor. Solid lines are judged links; dashed lines are embedding suggestions.'));
  heading.append(button('Refresh graph', () => showClusterGraph(activeGroup), 'refresh-map'));
  wrapper.append(heading, graphControls(data));
  if (!data.clusters.length) {
    wrapper.append(element('p', 'empty-map', 'No clusters in this view yet.'));
    graphTrack.replaceChildren(wrapper);
    return;
  }
  const width = Math.max(1200, Math.ceil(Math.sqrt(data.clusters.length)) * 160);
  const height = Math.max(800, Math.ceil(Math.sqrt(data.clusters.length)) * 120);
  const canvas = element('div', 'cluster-overview-canvas');
  canvas.style.width = `${width}px`;
  canvas.style.height = `${height}px`;
  const positions = clusterPosition(data.clusters, data.edges, width, height);
  const byId = new Map(positions.map(point => [point.id, point]));
  const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
  svg.setAttribute('viewBox', `0 0 ${width} ${height}`);
  svg.setAttribute('aria-hidden', 'true');
  svg.classList.add('cluster-overview-edges');
  for (const edge of data.edges) {
    const left = byId.get(edge.left);
    const right = byId.get(edge.right);
    if (!left || !right) continue;
    const line = document.createElementNS('http://www.w3.org/2000/svg', 'line');
    line.setAttribute('x1', left.x);
    line.setAttribute('y1', left.y);
    line.setAttribute('x2', right.x);
    line.setAttribute('y2', right.y);
    line.setAttribute('class', edge.basis);
    line.setAttribute('opacity', String(.22 + edge.score * .48));
    svg.append(line);
  }
  canvas.append(svg);
  for (const cluster of data.clusters) {
    const point = byId.get(cluster.id);
    const card = button('', () => showClusterFocus(cluster.id), 'cluster-node');
    card.style.left = `${point.x}px`;
    card.style.top = `${point.y}px`;
    card.append(element('span', 'eyebrow', `${cluster.size} ${cluster.size === 1 ? 'memory' : 'memories'}`), element('strong', '', cluster.label), element('small', '', cluster.arrangement?.primary?.replaceAll('_', ' + ') || 'graph'));
    canvas.append(card);
  }
  wrapper.append(canvas);
  graphTrack.replaceChildren(wrapper);
  document.getElementById('coverage').textContent = `${data.profiled_entries.toLocaleString()} profiled / ${data.total_entries.toLocaleString()} saved`;
  document.getElementById('map-status').textContent = `${data.cluster_count} persisted clusters · showing ${data.clusters.length}`;
}

async function showClusterGraph(groupId = null) {
  activeCluster = null;
  activeGroup = groupId;
  const ticket = ++graphTicket;
  graphTrack.replaceChildren(element('p', 'map-loading', 'Loading cluster graph...'));
  try {
    const data = await request(`/api/map/graph?limit=180${groupId ? `&group=${encodeURIComponent(groupId)}` : ''}`);
    if (ticket !== graphTicket) return;
    if (!data.ready) {
      graphTrack.replaceChildren(element('p', 'map-loading', 'The saved cluster projection is being prepared.'));
      return;
    }
    renderClusterGraph(data);
    viewport.scrollTo(0, 0);
  } catch {
    if (ticket === graphTicket) graphTrack.replaceChildren(element('p', 'map-loading', 'Could not load the cluster graph.'));
  }
}

function signalText(signals, kind, role) {
  const signal = (signals || []).find(item => item.kind === kind && (!role || item.role === role));
  return signal ? String(signal.value) : '';
}

function memoryCard(node) {
  const card = button('', () => openEntry(node.id), `focus-memory${node.quality === 'thin' ? ' thin' : ''}`);
  card.append(element('span', 'type', (node.type || 'Memory').replaceAll('_', ' ')), element('strong', '', node.label || node.id));
  const facts = [signalText(node.signals, 'time', 'event'), signalText(node.signals, 'sequence'), signalText(node.signals, 'place')].filter(Boolean);
  card.append(element('small', '', facts.join(' · ') || (node.concepts || []).slice(0, 2).join(' · ') || node.quality));
  return card;
}

function renderMembers(data) {
  const primary = data.arrangement?.primary || 'graph';
  const container = element('div', `focus-members layout-${primary}`);
  const nodes = [...data.nodes];
  const ordered = new Map((data.arrangement?.ordered_entry_ids || []).map((id, index) => [id, index]));
  if (['timeline', 'sequence', 'map_timeline'].includes(primary)) nodes.sort((a, b) => (ordered.get(a.id) ?? Infinity) - (ordered.get(b.id) ?? Infinity));
  for (const node of nodes) container.append(memoryCard(node));
  if (primary === 'map' || primary === 'map_timeline') container.prepend(element('p', 'layout-note', 'Place labels come from cited facts. Geographic positions need coordinates.'));
  if (primary === 'graph' && data.edges.length) {
    const list = element('div', 'focus-links');
    list.append(element('span', 'eyebrow', 'Judged links within this page'));
    for (const edge of data.edges.slice(0, 12)) list.append(element('span', '', `${Math.round(edge.score * 100)}% · ${data.nodes.find(node => node.id === edge.left)?.label || edge.left} ↔ ${data.nodes.find(node => node.id === edge.right)?.label || edge.right}`));
    container.append(list);
  }
  return container;
}

function neighborPreview(neighbor) {
  const card = button('', () => showClusterFocus(neighbor.id), 'neighbor-preview');
  card.append(element('span', 'eyebrow', `${neighbor.basis === 'judged' ? 'Judged' : 'Embedding suggestion'} · ${Math.round(neighbor.score * 100)}%`), element('strong', '', neighbor.label), element('small', '', `${neighbor.size} memories · ${neighbor.arrangement?.primary?.replaceAll('_', ' + ') || 'graph'}`));
  if (neighbor.summary) card.append(element('span', 'neighbor-summary', neighbor.summary));
  return card;
}

function renderClusterFocus(data) {
  const wrapper = element('section', 'cluster-focus');
  const heading = element('div', 'cluster-focus-heading');
  heading.append(button('← Cluster graph', () => showClusterGraph(activeGroup), 'back-graph'), element('p', 'eyebrow', `${data.size} memories · ${data.arrangement?.primary?.replaceAll('_', ' + ') || 'graph'}`), element('h1', '', data.label));
  if (data.summary) heading.append(element('p', 'cluster-summary', data.summary));
  const groups = element('div', 'focus-groups');
  for (const group of data.groups) groups.append(button(group.label, () => showClusterGraph(group.id)));
  heading.append(groups);
  wrapper.append(heading);
  const body = element('div', 'focus-body');
  const left = element('div', 'neighbor-rail');
  const right = element('div', 'neighbor-rail');
  left.append(element('span', 'eyebrow', 'Neighboring clusters'));
  right.append(element('span', 'eyebrow', 'More neighbors'));
  data.neighbors.forEach((neighbor, index) => (index % 2 ? right : left).append(neighborPreview(neighbor)));
  if (!data.neighbors.length) left.append(element('p', 'layout-note', 'No measured neighbors yet.'));
  const center = element('div', 'focus-center');
  center.append(renderMembers(data));
  if (data.pages > 1) {
    const pager = element('nav', 'focus-pager');
    const previous = button('Previous', () => showClusterFocus(data.id, data.page - 1));
    const next = button('Next', () => showClusterFocus(data.id, data.page + 1));
    previous.disabled = data.page === 0;
    next.disabled = data.page + 1 >= data.pages;
    pager.append(previous, element('span', '', `Page ${data.page + 1} of ${data.pages}`), next);
    center.append(pager);
  }
  body.append(left, center, right);
  wrapper.append(body);
  graphTrack.replaceChildren(wrapper);
  viewport.scrollTo(0, 0);
  document.getElementById('map-status').textContent = `${data.neighbors.length} ranked neighbors · judged links first`;
}

async function showClusterFocus(clusterId, page = 0) {
  activeCluster = clusterId;
  const ticket = ++graphTicket;
  graphTrack.replaceChildren(element('p', 'map-loading', 'Loading cluster...'));
  try {
    const data = await request(`/api/map/focus?id=${encodeURIComponent(clusterId)}&page=${page}`);
    if (ticket !== graphTicket) return;
    if (!data) throw new Error('Cluster missing');
    renderClusterFocus(data);
  } catch {
    if (ticket === graphTicket) graphTrack.replaceChildren(element('p', 'map-loading', 'Could not load this cluster. Refresh the graph.'));
  }
}

showClusterGraph();

