def do_chat(model, messages, tokens=1400):
    """Call DigitalOcean with bounded quota-aware retries and resumable pauses."""
    started = time.monotonic()
    url = os.environ.get("MGRAPH_DO_BASE_URL", "https://inference.do-ai.run").rstrip("/") + "/v1/chat/completions"
    reserve = int(os.environ.get("MGRAPH_DO_DAILY_RESERVE_TOKENS", "100000"))
    estimated_request = tokens + len(canonical(messages)) // 3
    with _quota_lock:
        if _quota_remaining_daily.get(model, reserve + estimated_request) < reserve + estimated_request:
            raise InferencePaused(f"DigitalOcean daily token allowance is below the {reserve:,}-token reserve; resume later")
    payload = {"model": model, "messages": messages, "max_completion_tokens": tokens, "temperature": 1 if model == "kimi-k2.6" else 0}
    effort = os.environ.get("MGRAPH_DO_REASONING_EFFORT")
    if effort:
        payload["reasoning_effort"] = effort
    with httpx.Client(timeout=float(os.environ.get("MGRAPH_DO_TIMEOUT_SECONDS", "240"))) as client:
        for attempt in range(5):
            try:
                response = client.post(url, headers={"Authorization": "Bearer " + os.environ["MGRAPH_DO_MODEL_ACCESS_KEY"]}, json=payload)
            except httpx.TransportError as error:
                if attempt == 4:
                    raise InferencePaused("DigitalOcean transport failed repeatedly; resume this stage later") from error
                time.sleep(min(2 ** attempt, 30))
                continue
            if response.status_code in (429, 503):
                delay = quota_retry_seconds(response, attempt)
                if delay > 120 or attempt == 4:
                    raise InferencePaused(f"DigitalOcean returned {response.status_code}; resume this stage after at least {int(delay + 0.999)} seconds")
                time.sleep(delay)
                continue
            response.raise_for_status()
            result = response.json()
            remaining = response.headers.get("x-ratelimit-remaining-tokens-per-day")
            if remaining is not None:
                try:
                    with _quota_lock:
                        _quota_remaining_daily[model] = int(remaining)
                except ValueError:
                    pass
            break
    return result["choices"][0]["message"].get("content") or "", result.get("usage", {}), time.monotonic() - started


def cf_ai_post(model, payload, timeout=90):
    """Call Cloudflare Workers AI with bounded retries and a resumable pause."""
    url = f"https://api.cloudflare.com/client/v4/accounts/{os.environ['MGRAPH_CLOUDFLARE_ACCOUNT_ID']}/ai/run/{model}"
    with httpx.Client(timeout=timeout) as client:
        for attempt in range(5):
            try:
                response = client.post(url, headers={"Authorization": "Bearer " + os.environ["MGRAPH_CLOUDFLARE_WORKERS_AI_API_TOKEN"]}, json=payload)
            except httpx.TransportError as error:
                if attempt == 4:
                    raise InferencePaused("Cloudflare transport failed repeatedly; resume this stage later") from error
                time.sleep(min(2 ** attempt, 30))
                continue
            if response.status_code in (429, 500, 502, 503, 504):
                delay = quota_retry_seconds(response, attempt)
                if delay > 120 or attempt == 4:
                    raise InferencePaused(f"Cloudflare returned {response.status_code}; resume this stage after at least {int(delay + 0.999)} seconds")
                time.sleep(delay)
                continue
            response.raise_for_status()
            return response.json()["result"]


def model_json(raw):
    raw = re.sub(r"^```(?:json)?\s*|\s*```$", "", raw.strip())
    return json.loads(raw)


