        raise ValueError("invalid segment profile")
    if not isinstance(part.get("property_facts", []), list):
        raise ValueError("invalid segment profile")
    if any(not isinstance(part.get(key), list) or any(not isinstance(value, str) for value in part[key]) for key in ("concepts", "tags", "domains", "uncertainty")):
        raise ValueError("invalid segment profile")
    passage_map = {passage["passage_id"]: passage for passage in passages}
    claims = []
    facts = []
    rejected = 0
