"""Focused tests for connected-only, bounded map pagination."""
import unittest
from unittest.mock import patch

from mgraph import query


class _Rows:
    def __init__(self, rows):
        self.rows = rows

    def __iter__(self):
        return iter(self.rows)

    def fetchall(self):
        return self.rows

    def fetchone(self):
        return self.rows[0]


class _Database:
    def __enter__(self):
        return self

    def __exit__(self, *_):
        return False

    def execute(self, statement, *_):
        if "SELECT entry_id FROM" in statement:
            return _Rows([(item,) for item in "abcde"])
        if "FROM test.relation" in statement:
            return _Rows([("a", "b", .8, "related"), ("b", "c", .4, "related"), ("c", "d", .9, "related"), ("d", "e", .3, "related")])
        if "FROM test.pair_feedback" in statement:
            return _Rows([("b", "c", .9, "same idea")])
        if "count(*) FROM test.entry" in statement:
            return _Rows([(5,)])
        if "FROM test.entry e JOIN" in statement:
            return _Rows([(item, item, "TEXT", "rich", {"concepts": [], "tags": []}) for item in "abcd"])
        if "FROM test.order_feedback" in statement:
            return _Rows([])
        raise AssertionError(statement)


class MapPaginationTests(unittest.TestCase):
    def test_feedback_connects_group_and_standalone_entry_is_excluded(self):
        previous = query._graph_cache.copy()
        query._graph_cache.update(at=0, value=None)
        try:
            with patch.object(query, "config", return_value="test"), patch.object(query, "database", return_value=_Database()):
                catalog = query.map_groups()
                self.assertEqual(catalog["connected_entries"], 4)
                self.assertEqual(catalog["group_count"], 1)
                self.assertEqual(catalog["groups"][0]["size"], 4)
