def cluster_graph(limit=180, group_id=None):
    """Return a bounded overview of persisted clusters and their typed links."""
    schema = config()
    limit = max(1, min(int(limit), 300))
    with database() as conn:
        generation = conn.execute(f"SELECT updated_at FROM {schema}.cluster_generation WHERE id=1").fetchone()
        if not generation:
            return {"ready": False, "clusters": [], "edges": [], "groups": []}
        groups = conn.execute(f"SELECT g.id,g.label,count(m.cluster_id) FROM {schema}.cluster_group g JOIN {schema}.cluster_group_member m ON m.group_id=g.id GROUP BY g.id,g.label ORDER BY count(m.cluster_id) DESC,g.label LIMIT 60").fetchall()
        if group_id:
            rows = conn.execute(f"SELECT c.id,c.label,c.summary,c.member_count,c.arrangement FROM {schema}.cluster c JOIN {schema}.cluster_group_member m ON m.cluster_id=c.id WHERE m.group_id=%s ORDER BY c.member_count DESC,c.id LIMIT %s", (group_id, limit)).fetchall()
        else:
            rows = conn.execute(f"SELECT id,label,summary,member_count,arrangement FROM {schema}.cluster WHERE member_count>1 ORDER BY member_count DESC,id LIMIT %s", (limit,)).fetchall()
        ids = [row[0] for row in rows]
        edges = conn.execute(f"SELECT left_id,right_id,basis,score FROM {schema}.cluster_edge WHERE left_id=ANY(%s) AND right_id=ANY(%s) ORDER BY CASE basis WHEN 'judged' THEN 0 ELSE 1 END,score DESC", (ids, ids)).fetchall() if ids else []
        counts = conn.execute(f"SELECT (SELECT count(*) FROM {schema}.cluster),(SELECT count(*) FROM {schema}.profile),(SELECT count(*) FROM {schema}.entry)").fetchone()
