        ids = [item[0] for item in member_rows]
        relation_rows = conn.execute(f"SELECT r.left_id,r.right_id,r.score,r.judgment->>'relation' FROM {schema}.relation r WHERE r.left_id=ANY(%s) AND r.right_id=ANY(%s) AND r.score>=0.65", (ids, ids)).fetchall() if ids else []
