"""Resumable, one-user Memotron graph backfill and inference pipeline."""
import argparse
import gzip
import hashlib
import heapq
import json
import os
import re
import sys
import threading
import time
from collections import defaultdict
from decimal import Decimal
from pathlib import Path

import boto3
import certifi
import httpx
import psycopg
from boto3.dynamodb.conditions import Key
from psycopg.types.json import Jsonb

from .profile_quality import anchor_saved_name, build_passages, concept_key, passage_batches, profile_issues, properties_from_facts, validate_profile_part

ROOT = Path(__file__).resolve().parents[1]
RESOURCES = ("node", "file", "link", "collection", "property", "linkTag")
PROFILE_VERSION = "profile-v7"
RELATION_VERSION = "relation-v1"
PROJECTION_VERSION = "projection-v3"
_quota_lock = threading.Lock()
_quota_remaining_daily = {}


class InferencePaused(RuntimeError):
    """Stop a resumable stage when provider quota or capacity cannot recover soon."""


def quota_retry_seconds(response, attempt):
    """Use DigitalOcean's refill projection or Retry-After before retrying."""
    delays = [min(2 ** attempt, 30)]
    retry_after = response.headers.get("retry-after")
    if retry_after:
        try:
            delays.append(float(retry_after))
        except ValueError:
            pass
    now = time.time()
    for bucket in ("requests", "tokens-per-minute", "tokens-per-day"):
        remaining = response.headers.get("x-ratelimit-remaining-" + bucket)
        reset = response.headers.get("x-ratelimit-reset-" + bucket)
        if remaining is None or reset is None:
            continue
        try:
            if float(remaining) <= 0 and float(reset) > 0:
                delays.append(float(reset) - now)
        except ValueError:
            pass
    return max(1.0, *delays)


def config():
    """Load ignored local credentials and validate the SQL namespace."""
    for line in (ROOT / ".env").read_text().splitlines():
        if line and not line.startswith("#") and "=" in line:
            key, value = line.split("=", 1)
            os.environ.setdefault(key.strip(), value.strip().strip('"').strip("'"))
    schema = os.environ.get("MGRAPH_DATABASE_SCHEMA", "mgraph_pilot")
    if not re.fullmatch(r"[a-z][a-z0-9_]*", schema):
        raise ValueError("Invalid database schema")
    return schema


def canonical(value):
    """Serialize DynamoDB records deterministically, preserving numeric values."""
    def default(item):
        if isinstance(item, Decimal):
            return float(item) if item % 1 else int(item)
        if isinstance(item, (bytes, bytearray)):
            return {"base64": __import__("base64").b64encode(item).decode()}
        raise TypeError(type(item).__name__)
    return json.dumps(value, sort_keys=True, ensure_ascii=False, separators=(",", ":"), default=default)


def sha(value):
    return hashlib.sha256(value.encode() if isinstance(value, str) else value).hexdigest()


def database():
    return psycopg.connect(os.environ["MGRAPH_DATABASE_URL"], sslmode="verify-full", sslrootcert=certifi.where())


def source():
    return aws_session().resource("dynamodb").Table(os.environ["MGRAPH_SOURCE_DYNAMODB_TABLE"])


def aws_session():
    """Resolve the configured read-only legacy AWS identity."""
    return boto3.Session(profile_name=os.environ.get("MGRAPH_SOURCE_AWS_PROFILE", "phidata"), region_name=os.environ.get("MGRAPH_SOURCE_AWS_REGION", "ap-south-1"))


def storage():
    return boto3.client("s3", endpoint_url=os.environ["MGRAPH_R2_ENDPOINT"], region_name=os.environ.get("MGRAPH_R2_REGION", "auto"), aws_access_key_id=os.environ["MGRAPH_R2_ACCESS_KEY_ID"], aws_secret_access_key=os.environ["MGRAPH_R2_SECRET_ACCESS_KEY"])


def object_key(kind, name):
    prefix = os.environ.get("MGRAPH_R2_PREFIX", "mgraph-pilot/").strip("/")
    return f"{prefix}/{os.environ['MGRAPH_SOURCE_USER_ID']}/{kind}/{name}"


def migrate(schema):
    """Create the isolated pilot schema and pgvector extension."""
    with database() as conn:
        for path in sorted((ROOT / "sql").glob("[0-9]*.sql")):
            conn.execute(path.read_text().format(schema=schema))
    print("migration applied")


def backfill(schema, page_limit):
    """Read DynamoDB account partitions and checkpoint compressed R2 pages."""
    table, r2 = source(), storage()
    with database() as conn:
        for resource in RESOURCES:
            last = conn.execute(f"SELECT page_number,next_key,complete FROM {schema}.snapshot_page WHERE resource=%s ORDER BY page_number DESC LIMIT 1", (resource,)).fetchone()
            if last and last[2]:
                print(f"{resource}: already complete", flush=True)
                continue
            cursor, page, total = (last[1], last[0] + 1, 0) if last else (None, 0, 0)
            if last and cursor is None:
                cursor = {"PK": os.environ["MGRAPH_SOURCE_USER_ID"] + "#" + resource, "SK": conn.execute(f"SELECT max(payload->>'SK') FROM {schema}.source_record WHERE resource=%s", (resource,)).fetchone()[0]}
            while True:
    entry_id, source_id = args.entry[0], args.source_node
    with database() as conn:
        row = conn.execute(f"SELECT evidence_refs FROM {schema}.entry WHERE id=%s", (entry_id,)).fetchone()
        if not row or source_id not in {entry_id} | {ref["id"] for ref in row[0]}:
            raise ValueError("source node is not part of the entry")
        key = object_key("manual", f"{sha(source_id)[:20]}-{sha(content)[:16]}.txt")
        storage().put_object(Bucket=os.environ["MGRAPH_R2_BUCKET"], Key=key, Body=content.encode(), ContentType="text/plain", Metadata={"sha256": sha(content)})
        conn.execute(f"INSERT INTO {schema}.extraction(entry_id,kind,source_hash,text_content,model,r2_key) VALUES (%s,%s,%s,%s,%s,%s) ON CONFLICT(entry_id,kind) DO UPDATE SET source_hash=excluded.source_hash,text_content=excluded.text_content,model=excluded.model,r2_key=excluded.r2_key,partial=false,updated_at=now()", (entry_id, "manual:" + source_id, sha(content), content, "manual-browser", key))
    print("manual extraction imported")


def main():
    parser = argparse.ArgumentParser(description="Memotron m graph pilot pipeline")
    parser.add_argument("command", choices=("migrate", "backfill", "project", "enrich-web", "enrich-audio", "enrich-image", "enrich-pdf", "import-text", "screen-web-identity", "repair-profile-names", "profile", "audit-profiles", "embed", "relate", "refresh-stale-relations", "relation-budgets", "refresh-graph", "enrich-signals", "annotate-clusters", "evaluate", "neighbors", "feedback-pair", "feedback-order", "status"))
    parser.add_argument("--limit", type=int)
    parser.add_argument("--target-total", type=int)
    parser.add_argument("--model")
    parser.add_argument("--per-entry", type=int, default=8)
    parser.add_argument("--shard", type=int, default=0)
    parser.add_argument("--shards", type=int, default=1)
    parser.add_argument("--entry", action="append")
    parser.add_argument("--left")
    parser.add_argument("--right")
    parser.add_argument("--anchor")
    parser.add_argument("--closer")
    parser.add_argument("--farther")
    parser.add_argument("--score", type=float)
    parser.add_argument("--label")
    parser.add_argument("--note")
    parser.add_argument("--refresh", action="store_true")
    parser.add_argument("--source-node")
    args = parser.parse_args()
    schema = config()
    if args.shards < 1 or args.shard < 0 or args.shard >= args.shards:
        raise ValueError("invalid shard")
    if args.command == "migrate":
        migrate(schema)
    elif args.command == "backfill":
        backfill(schema, args.limit)
    elif args.command == "project":
        project(schema)
    elif args.command in ("enrich-web", "enrich-audio", "enrich-image", "enrich-pdf"):
        from .extract import enrich
        enrich(schema, args.command.split("-", 1)[1], args.limit, args.shard, args.shards, set(args.entry or []), args.refresh)
    elif args.command == "import-text":
        import_text(schema, args)
    elif args.command == "screen-web-identity":
        from .web_identity import screen_web_identity
        screen_web_identity(schema, args.model or os.environ.get("MGRAPH_DO_IDENTITY_MODEL", "kimi-k3"), set(args.entry or []), args.limit)
    elif args.command == "repair-profile-names":
        repair_profile_names(schema)
    elif args.command == "profile":
        profile(schema, args.limit, args.model or os.environ.get("MGRAPH_DO_PROFILE_MODEL") or os.environ.get("MGRAPH_DO_REASONING_MODEL", "openai-gpt-oss-120b"), set(args.entry or []), args.shard, args.shards, bool(args.model))
    elif args.command == "audit-profiles":
        audit_profiles(schema, args.model or os.environ.get("MGRAPH_DO_PROFILE_MODEL") or os.environ.get("MGRAPH_DO_REASONING_MODEL", "openai-gpt-oss-120b"))
    elif args.command == "embed":
        embed(schema, args.limit, set(args.entry or []), args.shard, args.shards)
    elif args.command == "relate":
        relate(schema, args.limit, args.model or os.environ.get("MGRAPH_DO_RELATION_MODEL") or os.environ.get("MGRAPH_DO_REASONING_MODEL", "openai-gpt-oss-120b"), args.per_entry, (args.left, args.right) if args.left and args.right else None, args.shard, args.shards, args.target_total)
    elif args.command == "refresh-stale-relations":
        refresh_stale_relations(schema, args.model or os.environ.get("MGRAPH_DO_RELATION_MODEL") or os.environ.get("MGRAPH_DO_REASONING_MODEL", "openai-gpt-oss-120b"), args.shard, args.shards)
    elif args.command == "relation-budgets":
        for shard, budget in enumerate(relation_budgets(schema, args.shards, args.target_total or 20000)):
            print(shard, budget)
    elif args.command == "refresh-graph":
        from .cluster_pipeline import refresh_graph
        refresh_graph(schema)
