        from .cluster_pipeline import enrich_signals
        enrich_signals(schema, args.model or os.environ.get("MGRAPH_DO_PROFILE_MODEL", "kimi-k3"), args.limit, args.shard, args.shards, set(args.entry or []))
    elif args.command == "annotate-clusters":
        from .cluster_pipeline import annotate_clusters
        annotate_clusters(schema, args.model or os.environ.get("MGRAPH_DO_PROFILE_MODEL", "kimi-k3"), args.limit)
