        rr=c.execute(f"select r.left_id,r.right_id,r.score from {s}.relation r where r.left_id=any(%s) and r.right_id=any(%s)",(list(mids),list(mids))).fetchall()
        strong=[(a,b,score) for a,b,score in rr if score>=0.8]
        adj=defaultdict(list)
        for a,b,_ in strong:adj[a].append(b);adj[b].append(a)
        bridges=[]
