            seen={a};q=[a]
            while q:
                x=q.pop()
                for y in adj[x]:
                    if {x,y}=={a,b} or y in seen:continue
                    seen.add(y);q.append(y)
            if len(seen)<n:bridges.append((len(seen),n-len(seen),score))
        print(n,'judged',len(rr),'strong',len(strong),'bridges',bridges)
