"""Check conservative subdivisions of broad strong-link components."""
import unittest

from mgraph.cluster_projection import connected_components, subcluster_components


def edge(left, right, score):
    return {"left": left, "right": right, "score": score}


class SubclusteringTests(unittest.TestCase):
    def test_two_coherent_niches_split_under_one_parent(self):
        left = ("m1", "m2", "m3", "m4")
        right = ("d1", "d2", "d3", "d4")
        edges = {}
        for members in (left, right):
            for index, first in enumerate(members):
                for second in members[index + 1:]:
                    edges[(first, second)] = edge(first, second, 0.92)
        edges[("m4", "d1")] = edge("m4", "d1", 0.82)
        vectors = {entry_id: [1, 0.1 * index] for index, entry_id in enumerate(left)}
        vectors.update({entry_id: [0.1 * index, 1] for index, entry_id in enumerate(right)})
        components = connected_components(edges, 0.8)

        refined, parents = subcluster_components(components, edges, vectors)

        self.assertEqual({frozenset(item["members"]) for item in refined}, {frozenset(left), frozenset(right)})
        self.assertEqual([set(item["members"]) for item in parents], [set(left + right)])

    def test_linear_component_without_semantic_separation_stays_together(self):
        members = tuple("abcdef")
        edges = {(members[index], members[index + 1]): edge(members[index], members[index + 1], 0.88) for index in range(5)}
        vectors = {entry_id: [1, 0.01 * index] for index, entry_id in enumerate(members)}

        refined, parents = subcluster_components(connected_components(edges, 0.8), edges, vectors)

        self.assertEqual([set(item["members"]) for item in refined], [set(members)])
        self.assertEqual(parents, [])

    def test_missing_embeddings_do_not_force_a_split(self):
        members = tuple("abcdef")
        edges = {(members[index], members[index + 1]): edge(members[index], members[index + 1], 0.88) for index in range(5)}
        vectors = {entry_id: [1, 0] for entry_id in members[:-1]}

        refined, parents = subcluster_components(connected_components(edges, 0.8), edges, vectors)

        self.assertEqual(len(refined), 1)
        self.assertEqual(parents, [])


if __name__ == "__main__":
    unittest.main()

