    return json.loads(raw)


def profile_prompt(entry_id, kind, passages):
    """Ask for compact facts anchored to exact, individually numbered passages."""
    instruction = "Create an evidence-grounded memory profile. Return only JSON with summary (string), concepts (short natural-language phrase array), tags (short string array), domains (string array), uncertainty (string array), claims (array of objects with text, evidence_id, passage_id, quote, kind), and property_facts (array of objects with key, value, evidence_id, passage_id, quote, kind, confidence). For each claim and property, copy an exact supporting quote from the same passage_id and use that passage's evidence_id. A valid ID without a supporting quote is insufficient. kind must be observation, source_claim, user_hypothesis, or inference. Attribute vendor capabilities and performance claims to their source in the summary; treat a person's ideas as user_hypotheses rather than established facts. Keep speculative interpretation out of factual properties. confidence must be high, medium, or low. Omit uncertain phonetic names from audio properties. Use lowercase snake_case property keys, including name and url. Property facts should describe the entry or its core subject, not incidental bibliography, references, footer links, or navigational UI. Distinguish a precise niche from a broad domain. A changing price, count, or status is a snapshot observation, not an enduring fact. Include only useful, well-supported facts, at most eight claims and eight property facts per request. Ignore navigation and footer boilerplate in the summary."
    return [{"role": "system", "content": instruction}, {"role": "user", "content": canonical({"entry_id": entry_id, "content_type": kind, "passages": passages})}]


def merge_segment_profiles(partials, overview=None):
    """Retain all segment evidence while using a concise model overview when valid."""
    merged = {"summary": "", "concepts": [], "tags": [], "properties": {}, "claims": [], "domains": [], "uncertainty": []}
    summaries = []
    seen_claims = set()
    seen_facts = set()
    warnings = []
    for part in partials:
        if not isinstance(part, dict):
            raise ValueError("invalid segment profile")
        if isinstance(part.get("summary"), str) and part["summary"].strip():
            summaries.append(part["summary"].strip())
        for key in ("concepts", "tags", "domains", "uncertainty"):
            values = part.get(key)
            if not isinstance(values, list):
                raise ValueError("invalid segment profile")
            for value in values:
                already_present = any(concept_key(existing) == concept_key(value) for existing in merged[key]) if key in ("concepts", "tags", "domains") else value in merged[key]
                if isinstance(value, str) and not already_present:
                    merged[key].append(value)
        if not isinstance(part.get("properties"), dict) or not isinstance(part.get("claims"), list):
            raise ValueError("invalid segment profile")
        for key, value in part["properties"].items():
            if key in merged["properties"] and merged["properties"][key] != value:
                previous = merged["properties"][key]
                values = previous if isinstance(previous, list) else [previous]
                if value not in values:
                    merged["properties"][key] = values + [value]
                if not part.get("property_facts"):
                    warning = f"Different segment values for property {key}"
                    if warning not in merged["uncertainty"]:
                        merged["uncertainty"].append(warning)
                        warnings.append(warning)
            else:
                merged["properties"][key] = value
        for claim in part["claims"]:
            if isinstance(claim, dict):
                identifiers = claim.get("evidence_id")
                identifiers = identifiers if isinstance(identifiers, list) else [identifiers]
                for evidence_id in identifiers:
                    if isinstance(evidence_id, str):
                        evidence_id = evidence_id.strip("[]")
                    identifier = (claim.get("text"), evidence_id, claim.get("passage_id"))
