def _pieces(value):
    """Split long source text with short overlap and no omitted characters."""
    if not value:
        return []
    pieces = []
    start = 0
    while start < len(value):
        end = min(start + PASSAGE_CHARS, len(value))
        if end < len(value):
            boundary = max(value.rfind("\n", start + PASSAGE_CHARS // 2, end), value.rfind(" ", start + PASSAGE_CHARS // 2, end))
            if boundary > start:
                end = boundary + 1
        pieces.append(value[start:end])
        if end == len(value):
            break
        start = max(start + 1, end - PASSAGE_OVERLAP)
    return pieces


def build_passages(entry_id, source_text, extractions=None):
    """Preserve source-node identity while giving every quoted span a stable ID."""
    passages = []
    markers = re.split(r"(?m)^\[(node:[^\]\n]+)\]\n", source_text)
    source_blocks = [(markers[index], markers[index + 1]) for index in range(1, len(markers) - 1, 2)]
    if not source_blocks:
        source_blocks = [(entry_id, source_text)]
    blocks = [(source_id, "source", None, body) for source_id, body in source_blocks]
    for extraction in extractions or []:
        kind = str(extraction.get("kind") or "extraction")
        body = str(extraction.get("text") or "")
        source_id = kind.split(":", 1)[1] if ":" in kind else entry_id
        observed_at = extraction.get("observed_at")
        blocks.append((source_id, kind.split(":", 1)[0], str(observed_at) if observed_at else None, body))
    for source_id, origin, observed_at, body in blocks:
